Require Import Multivariate.context.
Axiom thm_T_DEF : forall (Ctx : HOL_Light_Theory), heq Ctx (htrue Ctx) (heq Ctx (fun p : Prop => p) (fun p : Prop => p)).
Axiom thm_AND_DEF : forall (Ctx : HOL_Light_Theory), heq Ctx (hand Ctx) (fun p : Prop => fun q : Prop => heq Ctx (fun f : Prop -> Prop -> Prop => f p q) (fun f : Prop -> Prop -> Prop => f (htrue Ctx) (htrue Ctx))).
Axiom thm_IMP_DEF : forall (Ctx : HOL_Light_Theory), heq Ctx imp (fun p : Prop => fun q : Prop => heq Ctx (hand Ctx p q) p).
Axiom thm_FORALL_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@all A) (fun P : A -> Prop => heq Ctx P (fun x : A => htrue Ctx)).
Axiom thm_EXISTS_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@hex Ctx A) (fun P : A -> Prop => all (fun q : Prop => (all (fun x : A => (P x) -> q)) -> q)).
Axiom thm_OR_DEF : forall (Ctx : HOL_Light_Theory), heq Ctx (hor Ctx) (fun p : Prop => fun q : Prop => all (fun r : Prop => (p -> r) -> (q -> r) -> r)).
Axiom thm_F_DEF : forall (Ctx : HOL_Light_Theory), heq Ctx (hfalse Ctx) (all (fun p : Prop => p)).
Axiom thm_NOT_DEF : forall (Ctx : HOL_Light_Theory), heq Ctx (not Ctx) (fun p : Prop => p -> hfalse Ctx).
Axiom thm_EXISTS_UNIQUE_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@hex1 Ctx A) (fun P : A -> Prop => hand Ctx (hex Ctx P) (all (fun x : A => all (fun y : A => (hand Ctx (P x) (P y)) -> heq Ctx x y)))).
Axiom thm__FALSITY_ : forall (Ctx : HOL_Light_Theory), heq Ctx (hFALSITY_ Ctx) (hfalse Ctx).
Axiom thm_EQ_REFL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => heq Ctx x x).
Axiom thm_REFL_CLAUSE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => heq Ctx (heq Ctx x x) (htrue Ctx)).
Axiom thm_EQ_SYM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun y : A => (heq Ctx x y) -> heq Ctx y x)).
Axiom thm_EQ_SYM_EQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun y : A => heq Ctx (heq Ctx x y) (heq Ctx y x))).
Axiom thm_EQ_TRANS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun y : A => all (fun z : A => (hand Ctx (heq Ctx x y) (heq Ctx y z)) -> heq Ctx x z))).
Axiom thm_BETA_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun y : A => heq Ctx ((fun x : A => f x) y) (f y))).
Axiom thm_ABS_SIMP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun t1 : A => all (fun t2 : B => heq Ctx ((fun x : B => t1) t2) t1)).
Axiom thm_CONJ_ASSOC : forall (Ctx : HOL_Light_Theory), all (fun t1 : Prop => all (fun t2 : Prop => all (fun t3 : Prop => heq Ctx (hand Ctx t1 (hand Ctx t2 t3)) (hand Ctx (hand Ctx t1 t2) t3)))).
Axiom thm_CONJ_SYM : forall (Ctx : HOL_Light_Theory), all (fun t1 : Prop => all (fun t2 : Prop => heq Ctx (hand Ctx t1 t2) (hand Ctx t2 t1))).
Axiom thm_CONJ_ACI : forall (Ctx : HOL_Light_Theory) (r : Prop) (p : Prop) (q : Prop), hand Ctx (heq Ctx (hand Ctx p q) (hand Ctx q p)) (hand Ctx (heq Ctx (hand Ctx (hand Ctx p q) r) (hand Ctx p (hand Ctx q r))) (hand Ctx (heq Ctx (hand Ctx p (hand Ctx q r)) (hand Ctx q (hand Ctx p r))) (hand Ctx (heq Ctx (hand Ctx p p) p) (heq Ctx (hand Ctx p (hand Ctx p q)) (hand Ctx p q))))).
Axiom thm_DISJ_ASSOC : forall (Ctx : HOL_Light_Theory), all (fun t1 : Prop => all (fun t2 : Prop => all (fun t3 : Prop => heq Ctx (hor Ctx t1 (hor Ctx t2 t3)) (hor Ctx (hor Ctx t1 t2) t3)))).
Axiom thm_DISJ_SYM : forall (Ctx : HOL_Light_Theory), all (fun t1 : Prop => all (fun t2 : Prop => heq Ctx (hor Ctx t1 t2) (hor Ctx t2 t1))).
Axiom thm_DISJ_ACI : forall (Ctx : HOL_Light_Theory) (r : Prop) (p : Prop) (q : Prop), hand Ctx (heq Ctx (hor Ctx p q) (hor Ctx q p)) (hand Ctx (heq Ctx (hor Ctx (hor Ctx p q) r) (hor Ctx p (hor Ctx q r))) (hand Ctx (heq Ctx (hor Ctx p (hor Ctx q r)) (hor Ctx q (hor Ctx p r))) (hand Ctx (heq Ctx (hor Ctx p p) p) (heq Ctx (hor Ctx p (hor Ctx p q)) (hor Ctx p q))))).
Axiom thm_IMP_CONJ : forall (Ctx : HOL_Light_Theory) (p : Prop) (q : Prop) (r : Prop), heq Ctx ((hand Ctx p q) -> r) (p -> q -> r).
Axiom thm_IMP_CONJ_ALT : forall (Ctx : HOL_Light_Theory) (q : Prop) (p : Prop) (r : Prop), heq Ctx ((hand Ctx p q) -> r) (q -> p -> r).
Axiom thm_LEFT_OR_DISTRIB : forall (Ctx : HOL_Light_Theory), all (fun p : Prop => all (fun q : Prop => all (fun r : Prop => heq Ctx (hand Ctx p (hor Ctx q r)) (hor Ctx (hand Ctx p q) (hand Ctx p r))))).
Axiom thm_RIGHT_OR_DISTRIB : forall (Ctx : HOL_Light_Theory), all (fun p : Prop => all (fun q : Prop => all (fun r : Prop => heq Ctx (hand Ctx (hor Ctx p q) r) (hor Ctx (hand Ctx p r) (hand Ctx q r))))).
Axiom thm_FORALL_SIMP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun t : Prop => heq Ctx (all (fun x : A => t)) t).
Axiom thm_EXISTS_SIMP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun t : Prop => heq Ctx (hex Ctx (fun x : A => t)) t).
Axiom thm_EQ_CLAUSES : forall (Ctx : HOL_Light_Theory), all (fun t : Prop => hand Ctx (heq Ctx (heq Ctx (htrue Ctx) t) t) (hand Ctx (heq Ctx (heq Ctx t (htrue Ctx)) t) (hand Ctx (heq Ctx (heq Ctx (hfalse Ctx) t) (not Ctx t)) (heq Ctx (heq Ctx t (hfalse Ctx)) (not Ctx t))))).
Axiom thm_NOT_CLAUSES_WEAK : forall (Ctx : HOL_Light_Theory), hand Ctx (heq Ctx (not Ctx (htrue Ctx)) (hfalse Ctx)) (heq Ctx (not Ctx (hfalse Ctx)) (htrue Ctx)).
Axiom thm_AND_CLAUSES : forall (Ctx : HOL_Light_Theory), all (fun t : Prop => hand Ctx (heq Ctx (hand Ctx (htrue Ctx) t) t) (hand Ctx (heq Ctx (hand Ctx t (htrue Ctx)) t) (hand Ctx (heq Ctx (hand Ctx (hfalse Ctx) t) (hfalse Ctx)) (hand Ctx (heq Ctx (hand Ctx t (hfalse Ctx)) (hfalse Ctx)) (heq Ctx (hand Ctx t t) t))))).
Axiom thm_OR_CLAUSES : forall (Ctx : HOL_Light_Theory), all (fun t : Prop => hand Ctx (heq Ctx (hor Ctx (htrue Ctx) t) (htrue Ctx)) (hand Ctx (heq Ctx (hor Ctx t (htrue Ctx)) (htrue Ctx)) (hand Ctx (heq Ctx (hor Ctx (hfalse Ctx) t) t) (hand Ctx (heq Ctx (hor Ctx t (hfalse Ctx)) t) (heq Ctx (hor Ctx t t) t))))).
Axiom thm_IMP_CLAUSES : forall (Ctx : HOL_Light_Theory), all (fun t : Prop => hand Ctx (heq Ctx ((htrue Ctx) -> t) t) (hand Ctx (heq Ctx (t -> htrue Ctx) (htrue Ctx)) (hand Ctx (heq Ctx ((hfalse Ctx) -> t) (htrue Ctx)) (hand Ctx (heq Ctx (t -> t) (htrue Ctx)) (heq Ctx (t -> hfalse Ctx) (not Ctx t)))))).
Axiom thm_EXISTS_UNIQUE_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (@hex1 Ctx A (fun x : A => P x)) (hand Ctx (hex Ctx (fun x : A => P x)) (all (fun x : A => all (fun x' : A => (hand Ctx (P x) (P x')) -> heq Ctx x x'))))).
Axiom thm_EXISTS_REFL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => hex Ctx (fun x : A => heq Ctx x a)).
Axiom thm_EXISTS_UNIQUE_REFL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => @hex1 Ctx A (fun x : A => heq Ctx x a)).
Axiom thm_UNWIND_THM1 : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun a : A => heq Ctx (hex Ctx (fun x : A => hand Ctx (heq Ctx a x) (P x))) (P a))).
Axiom thm_UNWIND_THM2 : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun a : A => heq Ctx (hex Ctx (fun x : A => hand Ctx (heq Ctx x a) (P x))) (P a))).
Axiom thm_FORALL_UNWIND_THM2 : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun a : A => heq Ctx (all (fun x : A => (heq Ctx x a) -> P x)) (P a))).
Axiom thm_FORALL_UNWIND_THM1 : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun a : A => heq Ctx (all (fun x : A => (heq Ctx a x) -> P x)) (P a))).
Axiom thm_SWAP_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => heq Ctx (all (fun x : A => all (fun y : B => P x y))) (all (fun y : B => all (fun x : A => P x y)))).
Axiom thm_SWAP_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => heq Ctx (hex Ctx (fun x : A => hex Ctx (fun y : B => P x y))) (hex Ctx (fun y : B => hex Ctx (fun x : A => P x y)))).
Axiom thm_FORALL_AND_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => heq Ctx (all (fun x : A => hand Ctx (P x) (Q x))) (hand Ctx (all (fun x : A => P x)) (all (fun x : A => Q x))))).
Axiom thm_AND_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => heq Ctx (hand Ctx (all (fun x : A => P x)) (all (fun x : A => Q x))) (all (fun x : A => hand Ctx (P x) (Q x))))).
Axiom thm_LEFT_AND_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (hand Ctx (all (fun x : A => P x)) Q) (all (fun x : A => hand Ctx (P x) Q)))).
Axiom thm_RIGHT_AND_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (hand Ctx P (all (fun x : A => Q x))) (all (fun x : A => hand Ctx P (Q x))))).
Axiom thm_EXISTS_OR_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => heq Ctx (hex Ctx (fun x : A => hor Ctx (P x) (Q x))) (hor Ctx (hex Ctx (fun x : A => P x)) (hex Ctx (fun x : A => Q x))))).
Axiom thm_OR_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => heq Ctx (hor Ctx (hex Ctx (fun x : A => P x)) (hex Ctx (fun x : A => Q x))) (hex Ctx (fun x : A => hor Ctx (P x) (Q x))))).
Axiom thm_LEFT_OR_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (hor Ctx (hex Ctx (fun x : A => P x)) Q) (hex Ctx (fun x : A => hor Ctx (P x) Q)))).
Axiom thm_RIGHT_OR_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (hor Ctx P (hex Ctx (fun x : A => Q x))) (hex Ctx (fun x : A => hor Ctx P (Q x))))).
Axiom thm_LEFT_EXISTS_AND_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (hex Ctx (fun x : A => hand Ctx (P x) Q)) (hand Ctx (hex Ctx (fun x : A => P x)) Q))).
Axiom thm_RIGHT_EXISTS_AND_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (hex Ctx (fun x : A => hand Ctx P (Q x))) (hand Ctx P (hex Ctx (fun x : A => Q x))))).
Axiom thm_TRIV_EXISTS_AND_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : Prop => heq Ctx (hex Ctx (fun x : A => hand Ctx P Q)) (hand Ctx (hex Ctx (fun x : A => P)) (hex Ctx (fun x : A => Q))))).
Axiom thm_LEFT_AND_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (hand Ctx (hex Ctx (fun x : A => P x)) Q) (hex Ctx (fun x : A => hand Ctx (P x) Q)))).
Axiom thm_RIGHT_AND_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (hand Ctx P (hex Ctx (fun x : A => Q x))) (hex Ctx (fun x : A => hand Ctx P (Q x))))).
Axiom thm_TRIV_AND_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : Prop => heq Ctx (hand Ctx (hex Ctx (fun x : A => P)) (hex Ctx (fun x : A => Q))) (hex Ctx (fun x : A => hand Ctx P Q)))).
Axiom thm_TRIV_FORALL_OR_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : Prop => heq Ctx (all (fun x : A => hor Ctx P Q)) (hor Ctx (all (fun x : A => P)) (all (fun x : A => Q))))).
Axiom thm_TRIV_OR_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : Prop => heq Ctx (hor Ctx (all (fun x : A => P)) (all (fun x : A => Q))) (all (fun x : A => hor Ctx P Q)))).
Axiom thm_RIGHT_IMP_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (P -> all (fun x : A => Q x)) (all (fun x : A => P -> Q x)))).
Axiom thm_RIGHT_FORALL_IMP_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (all (fun x : A => P -> Q x)) (P -> all (fun x : A => Q x)))).
Axiom thm_LEFT_IMP_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx ((hex Ctx (fun x : A => P x)) -> Q) (all (fun x : A => (P x) -> Q)))).
Axiom thm_LEFT_FORALL_IMP_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (all (fun x : A => (P x) -> Q)) ((hex Ctx (fun x : A => P x)) -> Q))).
Axiom thm_TRIV_FORALL_IMP_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : Prop => heq Ctx (all (fun x : A => P -> Q)) ((hex Ctx (fun x : A => P)) -> all (fun x : A => Q)))).
Axiom thm_TRIV_EXISTS_IMP_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : Prop => heq Ctx (hex Ctx (fun x : A => P -> Q)) ((all (fun x : A => P)) -> hex Ctx (fun x : A => Q)))).
Axiom thm_MONO_FORALL : forall (Ctx : HOL_Light_Theory) {A : Type'} (P : A -> Prop) (Q : A -> Prop), (all (fun x : A => (P x) -> Q x)) -> (all (fun x : A => P x)) -> all (fun x : A => Q x).
Axiom thm_MONO_EXISTS : forall (Ctx : HOL_Light_Theory) {A : Type'} (P : A -> Prop) (Q : A -> Prop), (all (fun x : A => (P x) -> Q x)) -> (hex Ctx (fun x : A => P x)) -> hex Ctx (fun x : A => Q x).
Axiom thm_WLOG_RELATION : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun R' : A -> A -> Prop => all (fun P : A -> A -> Prop => (hand Ctx (all (fun x : A => all (fun y : A => (P x y) -> P y x))) (hand Ctx (all (fun x : A => all (fun y : A => hor Ctx (R' x y) (R' y x)))) (all (fun x : A => all (fun y : A => (R' x y) -> P x y))))) -> all (fun x : A => all (fun y : A => P x y)))).
Axiom thm_EXISTS_UNIQUE_ALT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (@hex1 Ctx A (fun x : A => P x)) (hex Ctx (fun x : A => all (fun y : A => heq Ctx (P y) (heq Ctx x y))))).
Axiom thm_EXISTS_UNIQUE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (@hex1 Ctx A (fun x : A => P x)) (hex Ctx (fun x : A => hand Ctx (P x) (all (fun y : A => (P y) -> heq Ctx y x))))).
Axiom thm_ETA_AX : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun t : A -> B => heq Ctx (fun x : A => t x) t).
Axiom thm_EQ_EXT : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun g : A -> B => (all (fun x : A => heq Ctx (f x) (g x))) -> heq Ctx f g)).
Axiom thm_FUN_EQ_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun g : A -> B => heq Ctx (heq Ctx f g) (all (fun x : A => heq Ctx (f x) (g x))))).
Axiom thm_SELECT_AX : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun x : A => (P x) -> P (@ε Ctx A P))).
Axiom thm_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@hex Ctx A) (fun P : A -> Prop => P (@ε Ctx A P)).
Axiom thm_SELECT_REFL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => heq Ctx (@ε Ctx A (fun y : A => heq Ctx y x)) x).
Axiom thm_SELECT_UNIQUE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun x : A => (all (fun y : A => heq Ctx (P y) (heq Ctx y x))) -> heq Ctx (@ε Ctx A P) x)).
Axiom thm_EXCLUDED_MIDDLE : forall (Ctx : HOL_Light_Theory), all (fun t : Prop => hor Ctx t (not Ctx t)).
Axiom thm_BOOL_CASES_AX : forall (Ctx : HOL_Light_Theory), all (fun t : Prop => hor Ctx (heq Ctx t (htrue Ctx)) (heq Ctx t (hfalse Ctx))).
Axiom thm_DE_MORGAN_THM : forall (Ctx : HOL_Light_Theory), all (fun t1 : Prop => all (fun t2 : Prop => hand Ctx (heq Ctx (not Ctx (hand Ctx t1 t2)) (hor Ctx (not Ctx t1) (not Ctx t2))) (heq Ctx (not Ctx (hor Ctx t1 t2)) (hand Ctx (not Ctx t1) (not Ctx t2))))).
Axiom thm_NOT_CLAUSES : forall (Ctx : HOL_Light_Theory), hand Ctx (all (fun t : Prop => heq Ctx (not Ctx (not Ctx t)) t)) (hand Ctx (heq Ctx (not Ctx (htrue Ctx)) (hfalse Ctx)) (heq Ctx (not Ctx (hfalse Ctx)) (htrue Ctx))).
Axiom thm_NOT_IMP : forall (Ctx : HOL_Light_Theory), all (fun t1 : Prop => all (fun t2 : Prop => heq Ctx (not Ctx (t1 -> t2)) (hand Ctx t1 (not Ctx t2)))).
Axiom thm_CONTRAPOS_THM : forall (Ctx : HOL_Light_Theory), all (fun t1 : Prop => all (fun t2 : Prop => heq Ctx ((not Ctx t1) -> not Ctx t2) (t2 -> t1))).
Axiom thm_NOT_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (not Ctx (hex Ctx (fun x : A => P x))) (all (fun x : A => not Ctx (P x)))).
Axiom thm_EXISTS_NOT_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (hex Ctx (fun x : A => not Ctx (P x))) (not Ctx (all (fun x : A => P x)))).
Axiom thm_NOT_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (not Ctx (all (fun x : A => P x))) (hex Ctx (fun x : A => not Ctx (P x)))).
Axiom thm_FORALL_NOT_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (all (fun x : A => not Ctx (P x))) (not Ctx (hex Ctx (fun x : A => P x)))).
Axiom thm_FORALL_BOOL_THM : forall (Ctx : HOL_Light_Theory) (P : Prop -> Prop), heq Ctx (all (fun b : Prop => P b)) (hand Ctx (P (htrue Ctx)) (P (hfalse Ctx))).
Axiom thm_EXISTS_BOOL_THM : forall (Ctx : HOL_Light_Theory) (P : Prop -> Prop), heq Ctx (hex Ctx (fun b : Prop => P b)) (hor Ctx (P (htrue Ctx)) (P (hfalse Ctx))).
Axiom thm_LEFT_FORALL_OR_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (all (fun x : A => hor Ctx (P x) Q)) (hor Ctx (all (fun x : A => P x)) Q))).
Axiom thm_RIGHT_FORALL_OR_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (all (fun x : A => hor Ctx P (Q x))) (hor Ctx P (all (fun x : A => Q x))))).
Axiom thm_LEFT_OR_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (hor Ctx (all (fun x : A => P x)) Q) (all (fun x : A => hor Ctx (P x) Q)))).
Axiom thm_RIGHT_OR_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (hor Ctx P (all (fun x : A => Q x))) (all (fun x : A => hor Ctx P (Q x))))).
Axiom thm_LEFT_IMP_FORALL_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx ((all (fun x : A => P x)) -> Q) (hex Ctx (fun x : A => (P x) -> Q)))).
Axiom thm_LEFT_EXISTS_IMP_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : Prop => heq Ctx (hex Ctx (fun x : A => (P x) -> Q)) ((all (fun x : A => P x)) -> Q))).
Axiom thm_RIGHT_IMP_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (P -> hex Ctx (fun x : A => Q x)) (hex Ctx (fun x : A => P -> Q x)))).
Axiom thm_RIGHT_EXISTS_IMP_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : Prop => all (fun Q : A -> Prop => heq Ctx (hex Ctx (fun x : A => P -> Q x)) (P -> hex Ctx (fun x : A => Q x)))).
Axiom thm_COND_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@COND Ctx A) (fun t : Prop => fun t1 : A => fun t2 : A => @ε Ctx A (fun x : A => hand Ctx ((heq Ctx t (htrue Ctx)) -> heq Ctx x t1) ((heq Ctx t (hfalse Ctx)) -> heq Ctx x t2))).
Axiom thm_COND_CLAUSES : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun t1 : A => all (fun t2 : A => hand Ctx (heq Ctx (@COND Ctx A (htrue Ctx) t1 t2) t1) (heq Ctx (@COND Ctx A (hfalse Ctx) t1 t2) t2))).
Axiom thm_COND_EXPAND : forall (Ctx : HOL_Light_Theory), all (fun b : Prop => all (fun t1 : Prop => all (fun t2 : Prop => heq Ctx (@COND Ctx Prop b t1 t2) (hand Ctx (hor Ctx (not Ctx b) t1) (hor Ctx b t2))))).
Axiom thm_COND_ID : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun b : Prop => all (fun t : A => heq Ctx (@COND Ctx A b t t) t)).
Axiom thm_COND_RAND : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun b : Prop => all (fun f : A -> B => all (fun x : A => all (fun y : A => heq Ctx (f (@COND Ctx A b x y)) (@COND Ctx B b (f x) (f y)))))).
Axiom thm_COND_RATOR : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun b : Prop => all (fun f : A -> B => all (fun g : A -> B => all (fun x : A => heq Ctx (@COND Ctx (A -> B) b f g x) (@COND Ctx B b (f x) (g x)))))).
Axiom thm_COND_ABS : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun b : Prop => all (fun f : A -> B => all (fun g : A -> B => heq Ctx (fun x : A => @COND Ctx B b (f x) (g x)) (@COND Ctx (A -> B) b f g)))).
Axiom thm_COND_SWAP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun p : Prop => all (fun x : A => all (fun y : A => heq Ctx (@COND Ctx A (not Ctx p) x y) (@COND Ctx A p y x)))).
Axiom thm_MONO_COND : forall (Ctx : HOL_Light_Theory) (A : Prop) (C : Prop) (b : Prop) (B : Prop) (D : Prop), (hand Ctx (A -> B) (C -> D)) -> (@COND Ctx Prop b A C) -> @COND Ctx Prop b B D.
Axiom thm_COND_ELIM_THM : forall (Ctx : HOL_Light_Theory) {A : Type'} (x : A) (c : Prop) (P : A -> Prop) (y : A), heq Ctx (P (@COND Ctx A c x y)) (hand Ctx (c -> P x) ((not Ctx c) -> P y)).
Axiom thm_SKOLEM_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => heq Ctx (all (fun x : A => hex Ctx (fun y : B => P x y))) (hex Ctx (fun y : A -> B => all (fun x : A => P x (y x))))).
Axiom thm_SKOLEM_THM_GEN : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> Prop => all (fun R' : A -> B -> Prop => heq Ctx (all (fun x : A => (P x) -> hex Ctx (fun y : B => R' x y))) (hex Ctx (fun f : A -> B => all (fun x : A => (P x) -> R' x (f x)))))).
Axiom thm_UNIQUE_SKOLEM_ALT : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => heq Ctx (all (fun x : A => @hex1 Ctx B (fun y : B => P x y))) (hex Ctx (fun f : A -> B => all (fun x : A => all (fun y : B => heq Ctx (P x y) (heq Ctx (f x) y)))))).
Axiom thm_UNIQUE_SKOLEM_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => heq Ctx (all (fun x : A => @hex1 Ctx B (fun y : B => P x y))) (@hex1 Ctx (A -> B) (fun f : A -> B => all (fun x : A => P x (f x))))).
Axiom thm_bool_INDUCT : forall (Ctx : HOL_Light_Theory), all (fun P : Prop -> Prop => (hand Ctx (P (hfalse Ctx)) (P (htrue Ctx))) -> all (fun x : Prop => P x)).
Axiom thm_bool_RECURSION : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => all (fun b : A => hex Ctx (fun f : Prop -> A => hand Ctx (heq Ctx (f (hfalse Ctx)) a) (heq Ctx (f (htrue Ctx)) b)))).
Axiom thm_o_DEF : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : B -> C => all (fun g : A -> B => heq Ctx (@o Ctx A B C f g) (fun x : A => f (g x)))).
Axiom thm_I_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@I Ctx A) (fun x : A => x).
Axiom thm_o_THM : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : B -> C => all (fun g : A -> B => all (fun x : A => heq Ctx (@o Ctx A B C f g x) (f (g x))))).
Axiom thm_o_ASSOC : forall (Ctx : HOL_Light_Theory) {A B C D : Type'}, all (fun f : C -> D => all (fun g : B -> C => all (fun h : A -> B => heq Ctx (@o Ctx A C D f (@o Ctx A B C g h)) (@o Ctx A B D (@o Ctx B C D f g) h)))).
Axiom thm_I_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => heq Ctx (@I Ctx A x) x).
Axiom thm_I_O_ID : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => hand Ctx (heq Ctx (@o Ctx A B B (@I Ctx B) f) f) (heq Ctx (@o Ctx A A B f (@I Ctx A)) f)).
Axiom thm_EXISTS_ONE_REP : forall (Ctx : HOL_Light_Theory), hex Ctx (fun b : Prop => b).
Axiom thm_one_DEF : forall (Ctx : HOL_Light_Theory), heq Ctx (one Ctx) (@ε Ctx (hunit Ctx) (fun x : hunit Ctx => htrue Ctx)).
Axiom thm_one : forall (Ctx : HOL_Light_Theory), all (fun v : hunit Ctx => heq Ctx v (one Ctx)).
Axiom thm_one_axiom : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun f : A -> hunit Ctx => all (fun g : A -> hunit Ctx => heq Ctx f g)).
Axiom thm_one_INDUCT : forall (Ctx : HOL_Light_Theory), all (fun P : (hunit Ctx) -> Prop => (P (one Ctx)) -> all (fun x : hunit Ctx => P x)).
Axiom thm_one_RECURSION : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun e : A => hex Ctx (fun fn : (hunit Ctx) -> A => heq Ctx (fn (one Ctx)) e)).
Axiom thm_one_Axiom : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun e : A => @hex1 Ctx ((hunit Ctx) -> A) (fun fn : (hunit Ctx) -> A => heq Ctx (fn (one Ctx)) e)).
Axiom thm_FORALL_ONE_THM : forall (Ctx : HOL_Light_Theory) (P : (hunit Ctx) -> Prop), heq Ctx (all (fun x : hunit Ctx => P x)) (P (one Ctx)).
Axiom thm_EXISTS_ONE_THM : forall (Ctx : HOL_Light_Theory) (P : (hunit Ctx) -> Prop), heq Ctx (hex Ctx (fun x : hunit Ctx => P x)) (P (one Ctx)).
Axiom thm_ETA_ONE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun f : (hunit Ctx) -> A => heq Ctx (fun x : hunit Ctx => f (one Ctx)) f).
Axiom thm_LET_DEF : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun x : A => heq Ctx (@LET Ctx A B f x) (f x))).
Axiom thm_LET_END_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun t : A => heq Ctx (@LET_END Ctx A t) t).
Axiom thm_GABS_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => heq Ctx (@GABS Ctx A P) (@ε Ctx A P)).
Axiom thm_GEQ_DEF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => all (fun b : A => heq Ctx (@GEQ Ctx A a b) (heq Ctx a b))).
Axiom thm__SEQPATTERN : forall (Ctx : HOL_Light_Theory) {A B : Type'}, heq Ctx (@hSEQPATTERN Ctx A B) (fun r : A -> B -> Prop => fun s : A -> B -> Prop => fun x : A => @COND Ctx (B -> Prop) (hex Ctx (fun y : B => r x y)) (r x) (s x)).
Axiom thm__UNGUARDED_PATTERN : forall (Ctx : HOL_Light_Theory), heq Ctx (hUNGUARDED_PATTERN Ctx) (fun p : Prop => fun r : Prop => hand Ctx p r).
Axiom thm__GUARDED_PATTERN : forall (Ctx : HOL_Light_Theory), heq Ctx (hGUARDED_PATTERN Ctx) (fun p : Prop => fun g : Prop => fun r : Prop => hand Ctx p (hand Ctx g r)).
Axiom thm__MATCH : forall (Ctx : HOL_Light_Theory) {A B : Type'}, heq Ctx (@hMATCH Ctx A B) (fun e : A => fun r : A -> B -> Prop => @COND Ctx B (@hex1 Ctx B (r e)) (@ε Ctx B (r e)) (@ε Ctx B (fun z : B => hfalse Ctx))).
Axiom thm__FUNCTION : forall (Ctx : HOL_Light_Theory) {A B : Type'}, heq Ctx (@hFUNCTION Ctx A B) (fun r : A -> B -> Prop => fun x : A => @COND Ctx B (@hex1 Ctx B (r x)) (@ε Ctx B (r x)) (@ε Ctx B (fun z : B => hfalse Ctx))).
Axiom thm_mk_pair_def : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun x : A => all (fun y : B => heq Ctx (@mk_pair Ctx A B x y) (fun a : A => fun b : B => hand Ctx (heq Ctx a x) (heq Ctx b y)))).
Axiom thm_PAIR_EXISTS_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, hex Ctx (fun x : A -> B -> Prop => hex Ctx (fun a : A => hex Ctx (fun b : B => heq Ctx x (@mk_pair Ctx A B a b)))).
Axiom thm_REP_ABS_PAIR : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun x : A => all (fun y : B => heq Ctx (@REP_prod Ctx A B (@ABS_prod Ctx A B (@mk_pair Ctx A B x y))) (@mk_pair Ctx A B x y))).
Axiom thm_COMMA_DEF : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun x : A => all (fun y : B => heq Ctx (@hpair Ctx A B x y) (@ABS_prod Ctx A B (@mk_pair Ctx A B x y)))).
Axiom thm_FST_DEF : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun p : hprod Ctx A B => heq Ctx (@FST Ctx A B p) (@ε Ctx A (fun x : A => hex Ctx (fun y : B => heq Ctx p (@hpair Ctx A B x y))))).
Axiom thm_SND_DEF : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun p : hprod Ctx A B => heq Ctx (@SND Ctx A B p) (@ε Ctx B (fun y : B => hex Ctx (fun x : A => heq Ctx p (@hpair Ctx A B x y))))).
Axiom thm_PAIR_EQ : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun x : A => all (fun y : B => all (fun a : A => all (fun b : B => heq Ctx (heq Ctx (@hpair Ctx A B x y) (@hpair Ctx A B a b)) (hand Ctx (heq Ctx x a) (heq Ctx y b)))))).
Axiom thm_PAIR_SURJECTIVE : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun p : hprod Ctx A B => hex Ctx (fun x : A => hex Ctx (fun y : B => heq Ctx p (@hpair Ctx A B x y)))).
Axiom thm_FST : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun x : A => all (fun y : B => heq Ctx (@FST Ctx A B (@hpair Ctx A B x y)) x)).
Axiom thm_SND : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun x : A => all (fun y : B => heq Ctx (@SND Ctx A B (@hpair Ctx A B x y)) y)).
Axiom thm_PAIR : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun x : hprod Ctx A B => heq Ctx (@hpair Ctx A B (@FST Ctx A B x) (@SND Ctx A B x)) x).
Axiom thm_pair_INDUCT : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : (hprod Ctx A B) -> Prop => (all (fun x : A => all (fun y : B => P (@hpair Ctx A B x y)))) -> all (fun p : hprod Ctx A B => P p)).
Axiom thm_pair_RECURSION : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun PAIR' : A -> B -> C => hex Ctx (fun fn : (hprod Ctx A B) -> C => all (fun a0 : A => all (fun a1 : B => heq Ctx (fn (@hpair Ctx A B a0 a1)) (PAIR' a0 a1))))).
Axiom thm_CURRY_DEF : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : (hprod Ctx A B) -> C => all (fun x : A => all (fun y : B => heq Ctx (@CURRY Ctx A B C f x y) (f (@hpair Ctx A B x y))))).
Axiom thm_UNCURRY_DEF : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : A -> B -> C => all (fun x : A => all (fun y : B => heq Ctx (@UNCURRY Ctx A B C f (@hpair Ctx A B x y)) (f x y)))).
Axiom thm_PASSOC_DEF : forall (Ctx : HOL_Light_Theory) {A B C D : Type'}, all (fun f : (hprod Ctx (hprod Ctx A B) C) -> D => all (fun x : A => all (fun y : B => all (fun z : C => heq Ctx (@PASSOC Ctx A B C D f (@hpair Ctx A (hprod Ctx B C) x (@hpair Ctx B C y z))) (f (@hpair Ctx (hprod Ctx A B) C (@hpair Ctx A B x y) z)))))).
Axiom thm_FORALL_PAIR_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : (hprod Ctx A B) -> Prop => heq Ctx (all (fun p : hprod Ctx A B => P p)) (all (fun p1 : A => all (fun p2 : B => P (@hpair Ctx A B p1 p2))))).
Axiom thm_EXISTS_PAIR_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : (hprod Ctx A B) -> Prop => heq Ctx (hex Ctx (fun p : hprod Ctx A B => P p)) (hex Ctx (fun p1 : A => hex Ctx (fun p2 : B => P (@hpair Ctx A B p1 p2))))).
Axiom thm_LAMBDA_PAIR_THM : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun t : (hprod Ctx A B) -> C => heq Ctx (fun p : hprod Ctx A B => t p) (@GABS Ctx ((hprod Ctx A B) -> C) (fun f : (hprod Ctx A B) -> C => all (fun x : A => all (fun y : B => @GEQ Ctx C (f (@hpair Ctx A B x y)) (t (@hpair Ctx A B x y))))))).
Axiom thm_LAMBDA_PAIR : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : A -> B -> C => heq Ctx (@GABS Ctx ((hprod Ctx A B) -> C) (fun f' : (hprod Ctx A B) -> C => all (fun x : A => all (fun y : B => @GEQ Ctx C (f' (@hpair Ctx A B x y)) (f x y))))) (fun p : hprod Ctx A B => f (@FST Ctx A B p) (@SND Ctx A B p))).
Axiom thm_LAMBDA_TRIPLE_THM : forall (Ctx : HOL_Light_Theory) {A B C D : Type'}, all (fun f : (hprod Ctx A (hprod Ctx B C)) -> D => heq Ctx (fun t : hprod Ctx A (hprod Ctx B C) => f t) (@GABS Ctx ((hprod Ctx A (hprod Ctx B C)) -> D) (fun f' : (hprod Ctx A (hprod Ctx B C)) -> D => all (fun x : A => all (fun y : B => all (fun z : C => @GEQ Ctx D (f' (@hpair Ctx A (hprod Ctx B C) x (@hpair Ctx B C y z))) (f (@hpair Ctx A (hprod Ctx B C) x (@hpair Ctx B C y z))))))))).
Axiom thm_LAMBDA_TRIPLE : forall (Ctx : HOL_Light_Theory) {A B C D : Type'}, all (fun f : A -> B -> C -> D => heq Ctx (@GABS Ctx ((hprod Ctx A (hprod Ctx B C)) -> D) (fun f' : (hprod Ctx A (hprod Ctx B C)) -> D => all (fun x : A => all (fun y : B => all (fun z : C => @GEQ Ctx D (f' (@hpair Ctx A (hprod Ctx B C) x (@hpair Ctx B C y z))) (f x y z)))))) (fun t : hprod Ctx A (hprod Ctx B C) => f (@FST Ctx A (hprod Ctx B C) t) (@FST Ctx B C (@SND Ctx A (hprod Ctx B C) t)) (@SND Ctx B C (@SND Ctx A (hprod Ctx B C) t)))).
Axiom thm_PAIRED_ETA_THM : forall (Ctx : HOL_Light_Theory) {A B C D E : Type'}, hand Ctx (all (fun f : (hprod Ctx A B) -> C => heq Ctx (@GABS Ctx ((hprod Ctx A B) -> C) (fun f' : (hprod Ctx A B) -> C => all (fun x : A => all (fun y : B => @GEQ Ctx C (f' (@hpair Ctx A B x y)) (f (@hpair Ctx A B x y)))))) f)) (hand Ctx (all (fun f : (hprod Ctx A (hprod Ctx B C)) -> D => heq Ctx (@GABS Ctx ((hprod Ctx A (hprod Ctx B C)) -> D) (fun f' : (hprod Ctx A (hprod Ctx B C)) -> D => all (fun x : A => all (fun y : B => all (fun z : C => @GEQ Ctx D (f' (@hpair Ctx A (hprod Ctx B C) x (@hpair Ctx B C y z))) (f (@hpair Ctx A (hprod Ctx B C) x (@hpair Ctx B C y z)))))))) f)) (all (fun f : (hprod Ctx A (hprod Ctx B (hprod Ctx C D))) -> E => heq Ctx (@GABS Ctx ((hprod Ctx A (hprod Ctx B (hprod Ctx C D))) -> E) (fun f' : (hprod Ctx A (hprod Ctx B (hprod Ctx C D))) -> E => all (fun w : A => all (fun x : B => all (fun y : C => all (fun z : D => @GEQ Ctx E (f' (@hpair Ctx A (hprod Ctx B (hprod Ctx C D)) w (@hpair Ctx B (hprod Ctx C D) x (@hpair Ctx C D y z)))) (f (@hpair Ctx A (hprod Ctx B (hprod Ctx C D)) w (@hpair Ctx B (hprod Ctx C D) x (@hpair Ctx C D y z)))))))))) f))).
Axiom thm_FORALL_UNCURRY : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : (A -> B -> C) -> Prop => heq Ctx (all (fun f : A -> B -> C => P f)) (all (fun f : (hprod Ctx A B) -> C => P (fun a : A => fun b : B => f (@hpair Ctx A B a b))))).
Axiom thm_EXISTS_UNCURRY : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : (A -> B -> C) -> Prop => heq Ctx (hex Ctx (fun f : A -> B -> C => P f)) (hex Ctx (fun f : (hprod Ctx A B) -> C => P (fun a : A => fun b : B => f (@hpair Ctx A B a b))))).
Axiom thm_EXISTS_CURRY : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : ((hprod Ctx A B) -> C) -> Prop => heq Ctx (hex Ctx (fun f : (hprod Ctx A B) -> C => P f)) (hex Ctx (fun f : A -> B -> C => P (@GABS Ctx ((hprod Ctx A B) -> C) (fun f' : (hprod Ctx A B) -> C => all (fun a : A => all (fun b : B => @GEQ Ctx C (f' (@hpair Ctx A B a b)) (f a b)))))))).
Axiom thm_FORALL_CURRY : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : ((hprod Ctx A B) -> C) -> Prop => heq Ctx (all (fun f : (hprod Ctx A B) -> C => P f)) (all (fun f : A -> B -> C => P (@GABS Ctx ((hprod Ctx A B) -> C) (fun f' : (hprod Ctx A B) -> C => all (fun a : A => all (fun b : B => @GEQ Ctx C (f' (@hpair Ctx A B a b)) (f a b)))))))).
Axiom thm_FORALL_UNPAIR_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => heq Ctx (all (fun x : A => all (fun y : B => P x y))) (all (fun z : hprod Ctx A B => P (@FST Ctx A B z) (@SND Ctx A B z)))).
Axiom thm_EXISTS_UNPAIR_THM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => heq Ctx (hex Ctx (fun x : A => hex Ctx (fun y : B => P x y))) (hex Ctx (fun z : hprod Ctx A B => P (@FST Ctx A B z) (@SND Ctx A B z)))).
Axiom thm_FORALL_PAIR_FUN_THM : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : (A -> hprod Ctx B C) -> Prop => heq Ctx (all (fun f : A -> hprod Ctx B C => P f)) (all (fun g : A -> B => all (fun h : A -> C => P (fun a : A => @hpair Ctx B C (g a) (h a)))))).
Axiom thm_EXISTS_PAIR_FUN_THM : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : (A -> hprod Ctx B C) -> Prop => heq Ctx (hex Ctx (fun f : A -> hprod Ctx B C => P f)) (hex Ctx (fun g : A -> B => hex Ctx (fun h : A -> C => P (fun a : A => @hpair Ctx B C (g a) (h a)))))).
Axiom thm_FORALL_UNPAIR_FUN_THM : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : (A -> B) -> (A -> C) -> Prop => heq Ctx (all (fun f : A -> B => all (fun g : A -> C => P f g))) (all (fun h : A -> hprod Ctx B C => P (@o Ctx A (hprod Ctx B C) B (@FST Ctx B C) h) (@o Ctx A (hprod Ctx B C) C (@SND Ctx B C) h)))).
Axiom thm_EXISTS_UNPAIR_FUN_THM : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : (A -> B) -> (A -> C) -> Prop => heq Ctx (hex Ctx (fun f : A -> B => hex Ctx (fun g : A -> C => P f g))) (hex Ctx (fun h : A -> hprod Ctx B C => P (@o Ctx A (hprod Ctx B C) B (@FST Ctx B C) h) (@o Ctx A (hprod Ctx B C) C (@SND Ctx B C) h)))).
Axiom thm_EXISTS_SWAP_FUN_THM : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun P : (A -> B -> C) -> Prop => heq Ctx (hex Ctx (fun f : A -> B -> C => P f)) (hex Ctx (fun f : B -> A -> C => P (fun a : A => fun b : B => f b a)))).
