Axiom thm_NUMSUM_INJ : forall (Ctx : HOL_Light_Theory), all (fun b1 : Prop => all (fun x1 : num Ctx => all (fun b2 : Prop => all (fun x2 : num Ctx => heq Ctx (heq Ctx (NUMSUM Ctx b1 x1) (NUMSUM Ctx b2 x2)) (hand Ctx (heq Ctx b1 b2) (heq Ctx x1 x2)))))).
Axiom thm_INJN : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun m : num Ctx => heq Ctx (@INJN Ctx A m) (fun n : num Ctx => fun a : A => heq Ctx n m)).
Axiom thm_INJN_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun n1 : num Ctx => all (fun n2 : num Ctx => heq Ctx (heq Ctx (@INJN Ctx A n1) (@INJN Ctx A n2)) (heq Ctx n1 n2))).
Axiom thm_INJA : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => heq Ctx (@INJA Ctx A a) (fun n : num Ctx => fun b : A => heq Ctx b a)).
Axiom thm_INJA_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a1 : A => all (fun a2 : A => heq Ctx (heq Ctx (@INJA Ctx A a1) (@INJA Ctx A a2)) (heq Ctx a1 a2))).
Axiom thm_INJF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun f : (num Ctx) -> (num Ctx) -> A -> Prop => heq Ctx (@INJF Ctx A f) (fun n : num Ctx => f (NUMFST Ctx n) (NUMSND Ctx n))).
Axiom thm_INJF_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun f1 : (num Ctx) -> (num Ctx) -> A -> Prop => all (fun f2 : (num Ctx) -> (num Ctx) -> A -> Prop => heq Ctx (heq Ctx (@INJF Ctx A f1) (@INJF Ctx A f2)) (heq Ctx f1 f2))).
Axiom thm_INJP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun f1 : (num Ctx) -> A -> Prop => all (fun f2 : (num Ctx) -> A -> Prop => heq Ctx (@INJP Ctx A f1 f2) (fun n : num Ctx => fun a : A => @COND Ctx Prop (NUMLEFT Ctx n) (f1 (NUMRIGHT Ctx n) a) (f2 (NUMRIGHT Ctx n) a)))).
Axiom thm_INJP_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun f1 : (num Ctx) -> A -> Prop => all (fun f1' : (num Ctx) -> A -> Prop => all (fun f2 : (num Ctx) -> A -> Prop => all (fun f2' : (num Ctx) -> A -> Prop => heq Ctx (heq Ctx (@INJP Ctx A f1 f2) (@INJP Ctx A f1' f2')) (hand Ctx (heq Ctx f1 f1') (heq Ctx f2 f2')))))).
Axiom thm_ZCONSTR : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> (num Ctx) -> A -> Prop => heq Ctx (@ZCONSTR Ctx A c i r) (@INJP Ctx A (@INJN Ctx A (SUC Ctx c)) (@INJP Ctx A (@INJA Ctx A i) (@INJF Ctx A r)))))).
Axiom thm_ZBOT : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@ZBOT Ctx A) (@INJP Ctx A (@INJN Ctx A (NUMERAL Ctx (h0 Ctx))) (@ε Ctx ((num Ctx) -> A -> Prop) (fun z : (num Ctx) -> A -> Prop => htrue Ctx))).
Axiom thm_ZCONSTR_ZBOT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> (num Ctx) -> A -> Prop => not Ctx (heq Ctx (@ZCONSTR Ctx A c i r) (@ZBOT Ctx A))))).
Axiom thm_ZRECSPACE_RULES : forall (Ctx : HOL_Light_Theory) {A : Type'}, hand Ctx (@ZRECSPACE Ctx A (@ZBOT Ctx A)) (all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> (num Ctx) -> A -> Prop => (all (fun n : num Ctx => @ZRECSPACE Ctx A (r n))) -> @ZRECSPACE Ctx A (@ZCONSTR Ctx A c i r))))).
Axiom thm_ZRECSPACE_CASES : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : (num Ctx) -> A -> Prop => heq Ctx (@ZRECSPACE Ctx A a) (hor Ctx (heq Ctx a (@ZBOT Ctx A)) (hex Ctx (fun c : num Ctx => hex Ctx (fun i : A => hex Ctx (fun r : (num Ctx) -> (num Ctx) -> A -> Prop => hand Ctx (heq Ctx a (@ZCONSTR Ctx A c i r)) (all (fun n : num Ctx => @ZRECSPACE Ctx A (r n))))))))).
Axiom thm_ZRECSPACE_INDUCT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun ZRECSPACE' : ((num Ctx) -> A -> Prop) -> Prop => (hand Ctx (ZRECSPACE' (@ZBOT Ctx A)) (all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> (num Ctx) -> A -> Prop => (all (fun n : num Ctx => ZRECSPACE' (r n))) -> ZRECSPACE' (@ZCONSTR Ctx A c i r)))))) -> all (fun a : (num Ctx) -> A -> Prop => (@ZRECSPACE Ctx A a) -> ZRECSPACE' a)).
Axiom thm_BOTTOM : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@BOTTOM Ctx A) (@hmk_rec Ctx A (@ZBOT Ctx A)).
Axiom thm_CONSTR : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> recspace Ctx A => heq Ctx (@CONSTR Ctx A c i r) (@hmk_rec Ctx A (@ZCONSTR Ctx A c i (fun n : num Ctx => @hdest_rec Ctx A (r n))))))).
Axiom thm_MK_REC_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : (num Ctx) -> A -> Prop => all (fun y : (num Ctx) -> A -> Prop => (heq Ctx (@hmk_rec Ctx A x) (@hmk_rec Ctx A y)) -> (hand Ctx (@ZRECSPACE Ctx A x) (@ZRECSPACE Ctx A y)) -> heq Ctx x y)).
Axiom thm_DEST_REC_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : recspace Ctx A => all (fun y : recspace Ctx A => heq Ctx (heq Ctx (@hdest_rec Ctx A x) (@hdest_rec Ctx A y)) (heq Ctx x y))).
Axiom thm_CONSTR_BOT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> recspace Ctx A => not Ctx (heq Ctx (@CONSTR Ctx A c i r) (@BOTTOM Ctx A))))).
Axiom thm_CONSTR_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun c1 : num Ctx => all (fun i1 : A => all (fun r1 : (num Ctx) -> recspace Ctx A => all (fun c2 : num Ctx => all (fun i2 : A => all (fun r2 : (num Ctx) -> recspace Ctx A => heq Ctx (heq Ctx (@CONSTR Ctx A c1 i1 r1) (@CONSTR Ctx A c2 i2 r2)) (hand Ctx (heq Ctx c1 c2) (hand Ctx (heq Ctx i1 i2) (heq Ctx r1 r2))))))))).
Axiom thm_CONSTR_IND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (recspace Ctx A) -> Prop => (hand Ctx (P (@BOTTOM Ctx A)) (all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> recspace Ctx A => (all (fun n : num Ctx => P (r n))) -> P (@CONSTR Ctx A c i r)))))) -> all (fun x : recspace Ctx A => P x)).
Axiom thm_CONSTR_REC : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun Fn : (num Ctx) -> A -> ((num Ctx) -> recspace Ctx A) -> ((num Ctx) -> B) -> B => hex Ctx (fun f : (recspace Ctx A) -> B => all (fun c : num Ctx => all (fun i : A => all (fun r : (num Ctx) -> recspace Ctx A => heq Ctx (f (@CONSTR Ctx A c i r)) (Fn c i r (fun n : num Ctx => f (r n)))))))).
Axiom thm_FCONS : forall (Ctx : HOL_Light_Theory) {A : Type'}, hand Ctx (all (fun a : A => all (fun f : (num Ctx) -> A => heq Ctx (@FCONS Ctx A a f (NUMERAL Ctx (h0 Ctx))) a))) (all (fun a : A => all (fun f : (num Ctx) -> A => all (fun n : num Ctx => heq Ctx (@FCONS Ctx A a f (SUC Ctx n)) (f n))))).
Axiom thm_FCONS_UNDO : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun f : (num Ctx) -> A => heq Ctx f (@FCONS Ctx A (f (NUMERAL Ctx (h0 Ctx))) (@o Ctx (num Ctx) (num Ctx) A f (SUC Ctx)))).
Axiom thm_FNIL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun n : num Ctx => heq Ctx (@FNIL Ctx A n) (@ε Ctx A (fun x : A => htrue Ctx))).
Axiom thm_sum_INDUCT : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : (Sum Ctx A B) -> Prop => (hand Ctx (all (fun a : A => P (@INL Ctx A B a))) (all (fun a : B => P (@INR Ctx A B a)))) -> all (fun x : Sum Ctx A B => P x)).
Axiom thm_sum_RECURSION : forall (Ctx : HOL_Light_Theory) {A B Z' : Type'}, all (fun INL' : A -> Z' => all (fun INR' : B -> Z' => hex Ctx (fun fn : (Sum Ctx A B) -> Z' => hand Ctx (all (fun a : A => heq Ctx (fn (@INL Ctx A B a)) (INL' a))) (all (fun a : B => heq Ctx (fn (@INR Ctx A B a)) (INR' a)))))).
Axiom thm_OUTL : forall (Ctx : HOL_Light_Theory) {A B : Type'} (x : A), heq Ctx (@OUTL Ctx A B (@INL Ctx A B x)) x.
Axiom thm_OUTR : forall (Ctx : HOL_Light_Theory) {A B : Type'} (y : B), heq Ctx (@OUTR Ctx A B (@INR Ctx A B y)) y.
Axiom thm_option_INDUCT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (hoption Ctx A) -> Prop => (hand Ctx (P (@NONE Ctx A)) (all (fun a : A => P (@SOME Ctx A a)))) -> all (fun x : hoption Ctx A => P x)).
Axiom thm_option_RECURSION : forall (Ctx : HOL_Light_Theory) {A Z' : Type'}, all (fun NONE' : Z' => all (fun SOME' : A -> Z' => hex Ctx (fun fn : (hoption Ctx A) -> Z' => hand Ctx (heq Ctx (fn (@NONE Ctx A)) NONE') (all (fun a : A => heq Ctx (fn (@SOME Ctx A a)) (SOME' a)))))).
Axiom thm_list_INDUCT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (hlist Ctx A) -> Prop => (hand Ctx (P (@NIL Ctx A)) (all (fun a0 : A => all (fun a1 : hlist Ctx A => (P a1) -> P (@CONS Ctx A a0 a1))))) -> all (fun x : hlist Ctx A => P x)).
Axiom thm_list_RECURSION : forall (Ctx : HOL_Light_Theory) {A Z' : Type'}, all (fun NIL' : Z' => all (fun CONS' : A -> (hlist Ctx A) -> Z' -> Z' => hex Ctx (fun fn : (hlist Ctx A) -> Z' => hand Ctx (heq Ctx (fn (@NIL Ctx A)) NIL') (all (fun a0 : A => all (fun a1 : hlist Ctx A => heq Ctx (fn (@CONS Ctx A a0 a1)) (CONS' a0 a1 (fn a1)))))))).
Axiom thm_FORALL_OPTION_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (hoption Ctx A) -> Prop => heq Ctx (all (fun x : hoption Ctx A => P x)) (hand Ctx (P (@NONE Ctx A)) (all (fun a : A => P (@SOME Ctx A a))))).
Axiom thm_EXISTS_OPTION_THM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (hoption Ctx A) -> Prop => heq Ctx (hex Ctx (fun x : hoption Ctx A => P x)) (hor Ctx (P (@NONE Ctx A)) (hex Ctx (fun a : A => P (@SOME Ctx A a))))).
Axiom thm_option_DISTINCT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => not Ctx (heq Ctx (@SOME Ctx A a) (@NONE Ctx A))).
Axiom thm_option_INJ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => all (fun b : A => heq Ctx (heq Ctx (@SOME Ctx A a) (@SOME Ctx A b)) (heq Ctx a b))).
Axiom thm_ISO : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun g : B -> A => all (fun f : A -> B => heq Ctx (@ISO Ctx A B f g) (hand Ctx (all (fun x : B => heq Ctx (f (g x)) x)) (all (fun y : A => heq Ctx (g (f y)) y))))).
Axiom thm_ISO_REFL : forall (Ctx : HOL_Light_Theory) {A : Type'}, @ISO Ctx A A (fun x : A => x) (fun x : A => x).
Axiom thm_ISO_FUN : forall (Ctx : HOL_Light_Theory) {A A' B B' : Type'} (g : B -> B') (f' : A' -> A) (g' : B' -> B) (f : A -> A'), (hand Ctx (@ISO Ctx A A' f f') (@ISO Ctx B B' g g')) -> @ISO Ctx (A -> B) (A' -> B') (fun h : A -> B => fun a' : A' => g (h (f' a'))) (fun h : A' -> B' => fun a : A => g' (h (f a))).
Axiom thm_ISO_USAGE : forall (Ctx : HOL_Light_Theory) {A B : Type'} (g : B -> A) (f : A -> B), (@ISO Ctx A B f g) -> hand Ctx (all (fun P : A -> Prop => heq Ctx (all (fun x : A => P x)) (all (fun x : B => P (g x))))) (hand Ctx (all (fun P : A -> Prop => heq Ctx (hex Ctx (fun x : A => P x)) (hex Ctx (fun x : B => P (g x))))) (all (fun a : A => all (fun b : B => heq Ctx (heq Ctx a (g b)) (heq Ctx (f a) b))))).
Axiom thm_HD : forall (Ctx : HOL_Light_Theory) {A : Type'} (t : hlist Ctx A) (h : A), heq Ctx (@HD Ctx A (@CONS Ctx A h t)) h.
Axiom thm_TL : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (t : hlist Ctx A), heq Ctx (@TL Ctx A (@CONS Ctx A h t)) t.
Axiom thm_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, hand Ctx (all (fun l : hlist Ctx A => heq Ctx (@APPEND Ctx A (@NIL Ctx A) l) l)) (all (fun h : A => all (fun t : hlist Ctx A => all (fun l : hlist Ctx A => heq Ctx (@APPEND Ctx A (@CONS Ctx A h t) l) (@CONS Ctx A h (@APPEND Ctx A t l)))))).
Axiom thm_REVERSE : forall (Ctx : HOL_Light_Theory) {A : Type'} (l : hlist Ctx A) (x : A), hand Ctx (heq Ctx (@REVERSE Ctx A (@NIL Ctx A)) (@NIL Ctx A)) (heq Ctx (@REVERSE Ctx A (@CONS Ctx A x l)) (@APPEND Ctx A (@REVERSE Ctx A l) (@CONS Ctx A x (@NIL Ctx A)))).
Axiom thm_LENGTH : forall (Ctx : HOL_Light_Theory) {A : Type'}, hand Ctx (heq Ctx (@LENGTH Ctx A (@NIL Ctx A)) (NUMERAL Ctx (h0 Ctx))) (all (fun h : A => all (fun t : hlist Ctx A => heq Ctx (@LENGTH Ctx A (@CONS Ctx A h t)) (SUC Ctx (@LENGTH Ctx A t))))).
Axiom thm_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, hand Ctx (all (fun f : A -> B => heq Ctx (@MAP Ctx A B f (@NIL Ctx A)) (@NIL Ctx B))) (all (fun f : A -> B => all (fun h : A => all (fun t : hlist Ctx A => heq Ctx (@MAP Ctx A B f (@CONS Ctx A h t)) (@CONS Ctx B (f h) (@MAP Ctx A B f t)))))).
Axiom thm_LAST : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (t : hlist Ctx A), heq Ctx (@LAST Ctx A (@CONS Ctx A h t)) (@COND Ctx A (heq Ctx t (@NIL Ctx A)) h (@LAST Ctx A t)).
Axiom thm_BUTLAST : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (t : hlist Ctx A), hand Ctx (heq Ctx (@BUTLAST Ctx A (@NIL Ctx A)) (@NIL Ctx A)) (heq Ctx (@BUTLAST Ctx A (@CONS Ctx A h t)) (@COND Ctx (hlist Ctx A) (heq Ctx t (@NIL Ctx A)) (@NIL Ctx A) (@CONS Ctx A h (@BUTLAST Ctx A t)))).
Axiom thm_REPLICATE : forall (Ctx : HOL_Light_Theory) {A : Type'} (n : num Ctx) (x : A), hand Ctx (heq Ctx (@REPLICATE Ctx A (NUMERAL Ctx (h0 Ctx)) x) (@NIL Ctx A)) (heq Ctx (@REPLICATE Ctx A (SUC Ctx n) x) (@CONS Ctx A x (@REPLICATE Ctx A n x))).
Axiom thm_NULL : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (t : hlist Ctx A), hand Ctx (heq Ctx (@NULL Ctx A (@NIL Ctx A)) (htrue Ctx)) (heq Ctx (@NULL Ctx A (@CONS Ctx A h t)) (hfalse Ctx)).
Axiom thm_ALL : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (P : A -> Prop) (t : hlist Ctx A), hand Ctx (heq Ctx (@ALL Ctx A P (@NIL Ctx A)) (htrue Ctx)) (heq Ctx (@ALL Ctx A P (@CONS Ctx A h t)) (hand Ctx (P h) (@ALL Ctx A P t))).
Axiom thm_EX : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (P : A -> Prop) (t : hlist Ctx A), hand Ctx (heq Ctx (@EX Ctx A P (@NIL Ctx A)) (hfalse Ctx)) (heq Ctx (@EX Ctx A P (@CONS Ctx A h t)) (hor Ctx (P h) (@EX Ctx A P t))).
Axiom thm_ITLIST : forall (Ctx : HOL_Light_Theory) {A B : Type'} (h : A) (f : A -> B -> B) (t : hlist Ctx A) (b : B), hand Ctx (heq Ctx (@ITLIST Ctx A B f (@NIL Ctx A) b) b) (heq Ctx (@ITLIST Ctx A B f (@CONS Ctx A h t) b) (f h (@ITLIST Ctx A B f t b))).
Axiom thm_MEM : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (x : A) (t : hlist Ctx A), hand Ctx (heq Ctx (@MEM Ctx A x (@NIL Ctx A)) (hfalse Ctx)) (heq Ctx (@MEM Ctx A x (@CONS Ctx A h t)) (hor Ctx (heq Ctx x h) (@MEM Ctx A x t))).
Axiom thm_ALL2_DEF : forall (Ctx : HOL_Light_Theory) {A B : Type'} (h1' : A) (P : A -> B -> Prop) (t1 : hlist Ctx A) (l2 : hlist Ctx B), hand Ctx (heq Ctx (@ALL2 Ctx A B P (@NIL Ctx A) l2) (heq Ctx l2 (@NIL Ctx B))) (heq Ctx (@ALL2 Ctx A B P (@CONS Ctx A h1' t1) l2) (@COND Ctx Prop (heq Ctx l2 (@NIL Ctx B)) (hfalse Ctx) (hand Ctx (P h1' (@HD Ctx B l2)) (@ALL2 Ctx A B P t1 (@TL Ctx B l2))))).
Axiom thm_ALL2 : forall (Ctx : HOL_Light_Theory) {A B : Type'} (h1' : A) (h2' : B) (P : A -> B -> Prop) (t1 : hlist Ctx A) (t2 : hlist Ctx B), hand Ctx (heq Ctx (@ALL2 Ctx A B P (@NIL Ctx A) (@NIL Ctx B)) (htrue Ctx)) (hand Ctx (heq Ctx (@ALL2 Ctx A B P (@CONS Ctx A h1' t1) (@NIL Ctx B)) (hfalse Ctx)) (hand Ctx (heq Ctx (@ALL2 Ctx A B P (@NIL Ctx A) (@CONS Ctx B h2' t2)) (hfalse Ctx)) (heq Ctx (@ALL2 Ctx A B P (@CONS Ctx A h1' t1) (@CONS Ctx B h2' t2)) (hand Ctx (P h1' h2') (@ALL2 Ctx A B P t1 t2))))).
Axiom thm_MAP2_DEF : forall (Ctx : HOL_Light_Theory) {A B C : Type'} (h1' : A) (f : A -> B -> C) (t1 : hlist Ctx A) (l : hlist Ctx B), hand Ctx (heq Ctx (@MAP2 Ctx A B C f (@NIL Ctx A) l) (@NIL Ctx C)) (heq Ctx (@MAP2 Ctx A B C f (@CONS Ctx A h1' t1) l) (@CONS Ctx C (f h1' (@HD Ctx B l)) (@MAP2 Ctx A B C f t1 (@TL Ctx B l)))).
Axiom thm_MAP2 : forall (Ctx : HOL_Light_Theory) {A B C : Type'} (h1' : A) (h2' : B) (f : A -> B -> C) (t1 : hlist Ctx A) (t2 : hlist Ctx B), hand Ctx (heq Ctx (@MAP2 Ctx A B C f (@NIL Ctx A) (@NIL Ctx B)) (@NIL Ctx C)) (heq Ctx (@MAP2 Ctx A B C f (@CONS Ctx A h1' t1) (@CONS Ctx B h2' t2)) (@CONS Ctx C (f h1' h2') (@MAP2 Ctx A B C f t1 t2))).
Axiom thm_EL : forall (Ctx : HOL_Light_Theory) {A : Type'} (n : num Ctx) (l : hlist Ctx A), hand Ctx (heq Ctx (@EL Ctx A (NUMERAL Ctx (h0 Ctx)) l) (@HD Ctx A l)) (heq Ctx (@EL Ctx A (SUC Ctx n) l) (@EL Ctx A n (@TL Ctx A l))).
Axiom thm_FILTER : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (P : A -> Prop) (t : hlist Ctx A), hand Ctx (heq Ctx (@FILTER Ctx A P (@NIL Ctx A)) (@NIL Ctx A)) (heq Ctx (@FILTER Ctx A P (@CONS Ctx A h t)) (@COND Ctx (hlist Ctx A) (P h) (@CONS Ctx A h (@FILTER Ctx A P t)) (@FILTER Ctx A P t))).
Axiom thm_ASSOC : forall (Ctx : HOL_Light_Theory) {A B : Type'} (h : hprod Ctx A B) (a : A) (t : hlist Ctx (hprod Ctx A B)), heq Ctx (@ASSOC Ctx A B a (@CONS Ctx (hprod Ctx A B) h t)) (@COND Ctx B (heq Ctx (@FST Ctx A B h) a) (@SND Ctx A B h) (@ASSOC Ctx A B a t)).
Axiom thm_ITLIST2_DEF : forall (Ctx : HOL_Light_Theory) {A B C : Type'} (h1' : A) (f : A -> B -> C -> C) (t1 : hlist Ctx A) (l2 : hlist Ctx B) (b : C), hand Ctx (heq Ctx (@ITLIST2 Ctx A B C f (@NIL Ctx A) l2 b) b) (heq Ctx (@ITLIST2 Ctx A B C f (@CONS Ctx A h1' t1) l2 b) (f h1' (@HD Ctx B l2) (@ITLIST2 Ctx A B C f t1 (@TL Ctx B l2) b))).
Axiom thm_ITLIST2 : forall (Ctx : HOL_Light_Theory) {A B C : Type'} (h1' : A) (h2' : B) (f : A -> B -> C -> C) (t1 : hlist Ctx A) (t2 : hlist Ctx B) (b : C), hand Ctx (heq Ctx (@ITLIST2 Ctx A B C f (@NIL Ctx A) (@NIL Ctx B) b) b) (heq Ctx (@ITLIST2 Ctx A B C f (@CONS Ctx A h1' t1) (@CONS Ctx B h2' t2) b) (f h1' h2' (@ITLIST2 Ctx A B C f t1 t2 b))).
Axiom thm_ZIP_DEF : forall (Ctx : HOL_Light_Theory) {A B : Type'} (h1' : A) (t1 : hlist Ctx A) (l2 : hlist Ctx B), hand Ctx (heq Ctx (@ZIP Ctx A B (@NIL Ctx A) l2) (@NIL Ctx (hprod Ctx A B))) (heq Ctx (@ZIP Ctx A B (@CONS Ctx A h1' t1) l2) (@CONS Ctx (hprod Ctx A B) (@hpair Ctx A B h1' (@HD Ctx B l2)) (@ZIP Ctx A B t1 (@TL Ctx B l2)))).
Axiom thm_ZIP : forall (Ctx : HOL_Light_Theory) {A B : Type'} (h1' : A) (h2' : B) (t1 : hlist Ctx A) (t2 : hlist Ctx B), hand Ctx (heq Ctx (@ZIP Ctx A B (@NIL Ctx A) (@NIL Ctx B)) (@NIL Ctx (hprod Ctx A B))) (heq Ctx (@ZIP Ctx A B (@CONS Ctx A h1' t1) (@CONS Ctx B h2' t2)) (@CONS Ctx (hprod Ctx A B) (@hpair Ctx A B h1' h2') (@ZIP Ctx A B t1 t2))).
Axiom thm_ALLPAIRS : forall (Ctx : HOL_Light_Theory) {A B : Type'} (h : A) (f : A -> B -> Prop) (t : hlist Ctx A) (l : hlist Ctx B), hand Ctx (heq Ctx (@ALLPAIRS Ctx A B f (@NIL Ctx A) l) (htrue Ctx)) (heq Ctx (@ALLPAIRS Ctx A B f (@CONS Ctx A h t) l) (hand Ctx (@ALL Ctx B (f h) l) (@ALLPAIRS Ctx A B f t l))).
Axiom thm_PAIRWISE : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (r : A -> A -> Prop) (t : hlist Ctx A), hand Ctx (heq Ctx (@PAIRWISE Ctx A r (@NIL Ctx A)) (htrue Ctx)) (heq Ctx (@PAIRWISE Ctx A r (@CONS Ctx A h t)) (hand Ctx (@ALL Ctx A (r h) t) (@PAIRWISE Ctx A r t))).
Axiom thm_list_of_seq : forall (Ctx : HOL_Light_Theory) {A : Type'} (s : (num Ctx) -> A) (n : num Ctx), hand Ctx (heq Ctx (@list_of_seq Ctx A s (NUMERAL Ctx (h0 Ctx))) (@NIL Ctx A)) (heq Ctx (@list_of_seq Ctx A s (SUC Ctx n)) (@APPEND Ctx A (@list_of_seq Ctx A s n) (@CONS Ctx A (s n) (@NIL Ctx A)))).
Axiom thm_NOT_CONS_NIL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun h : A => all (fun t : hlist Ctx A => not Ctx (heq Ctx (@CONS Ctx A h t) (@NIL Ctx A)))).
Axiom thm_LAST_CLAUSES : forall (Ctx : HOL_Light_Theory) {A : Type'} (h : A) (k : A) (t : hlist Ctx A), hand Ctx (heq Ctx (@LAST Ctx A (@CONS Ctx A h (@NIL Ctx A))) h) (heq Ctx (@LAST Ctx A (@CONS Ctx A h (@CONS Ctx A k t))) (@LAST Ctx A (@CONS Ctx A k t))).
Axiom thm_APPEND_NIL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (@APPEND Ctx A l (@NIL Ctx A)) l).
Axiom thm_APPEND_ASSOC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => all (fun n : hlist Ctx A => heq Ctx (@APPEND Ctx A l (@APPEND Ctx A m n)) (@APPEND Ctx A (@APPEND Ctx A l m) n)))).
Axiom thm_REVERSE_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => heq Ctx (@REVERSE Ctx A (@APPEND Ctx A l m)) (@APPEND Ctx A (@REVERSE Ctx A m) (@REVERSE Ctx A l)))).
Axiom thm_REVERSE_REVERSE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (@REVERSE Ctx A (@REVERSE Ctx A l)) l).
Axiom thm_REVERSE_EQ_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (heq Ctx (@REVERSE Ctx A l) (@NIL Ctx A)) (heq Ctx l (@NIL Ctx A))).
Axiom thm_CONS_11 : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun h1' : A => all (fun h2' : A => all (fun t1 : hlist Ctx A => all (fun t2 : hlist Ctx A => heq Ctx (heq Ctx (@CONS Ctx A h1' t1) (@CONS Ctx A h2' t2)) (hand Ctx (heq Ctx h1' h2') (heq Ctx t1 t2)))))).
Axiom thm_list_CASES : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => hor Ctx (heq Ctx l (@NIL Ctx A)) (hex Ctx (fun h : A => hex Ctx (fun t : hlist Ctx A => heq Ctx l (@CONS Ctx A h t))))).
Axiom thm_LIST_EQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => heq Ctx (heq Ctx l1 l2) (hand Ctx (heq Ctx (@LENGTH Ctx A l1) (@LENGTH Ctx A l2)) (all (fun n : num Ctx => (lt Ctx n (@LENGTH Ctx A l2)) -> heq Ctx (@EL Ctx A n l1) (@EL Ctx A n l2)))))).
Axiom thm_LENGTH_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => heq Ctx (@LENGTH Ctx A (@APPEND Ctx A l m)) (add Ctx (@LENGTH Ctx A l) (@LENGTH Ctx A m)))).
Axiom thm_MAP_APPEND : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => heq Ctx (@MAP Ctx A B f (@APPEND Ctx A l1 l2)) (@APPEND Ctx B (@MAP Ctx A B f l1) (@MAP Ctx A B f l2))))).
Axiom thm_LENGTH_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun l : hlist Ctx A => all (fun f : A -> B => heq Ctx (@LENGTH Ctx B (@MAP Ctx A B f l)) (@LENGTH Ctx A l))).
Axiom thm_LENGTH_EQ_NIL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (heq Ctx (@LENGTH Ctx A l) (NUMERAL Ctx (h0 Ctx))) (heq Ctx l (@NIL Ctx A))).
Axiom thm_LENGTH_EQ_CONS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun n : num Ctx => heq Ctx (heq Ctx (@LENGTH Ctx A l) (SUC Ctx n)) (hex Ctx (fun h : A => hex Ctx (fun t : hlist Ctx A => hand Ctx (heq Ctx l (@CONS Ctx A h t)) (heq Ctx (@LENGTH Ctx A t) n)))))).
Axiom thm_LENGTH_REVERSE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (@LENGTH Ctx A (@REVERSE Ctx A l)) (@LENGTH Ctx A l)).
Axiom thm_MAP_o : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : A -> B => all (fun g : B -> C => all (fun l : hlist Ctx A => heq Ctx (@MAP Ctx A C (@o Ctx A B C g f) l) (@MAP Ctx B C g (@MAP Ctx A B f l))))).
Axiom thm_MAP_EQ : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun g : A -> B => all (fun l : hlist Ctx A => (@ALL Ctx A (fun x : A => heq Ctx (f x) (g x)) l) -> heq Ctx (@MAP Ctx A B f l) (@MAP Ctx A B g l)))).
Axiom thm_ALL_IMP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => all (fun l : hlist Ctx A => (hand Ctx (all (fun x : A => (hand Ctx (@MEM Ctx A x l) (P x)) -> Q x)) (@ALL Ctx A P l)) -> @ALL Ctx A Q l))).
Axiom thm_NOT_EX : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l : hlist Ctx A => heq Ctx (not Ctx (@EX Ctx A P l)) (@ALL Ctx A (fun x : A => not Ctx (P x)) l))).
Axiom thm_NOT_ALL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l : hlist Ctx A => heq Ctx (not Ctx (@ALL Ctx A P l)) (@EX Ctx A (fun x : A => not Ctx (P x)) l))).
Axiom thm_ALL_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : B -> Prop => all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (@ALL Ctx B P (@MAP Ctx A B f l)) (@ALL Ctx A (@o Ctx A B Prop P f) l)))).
Axiom thm_ALL_EQ : forall (Ctx : HOL_Light_Theory) {A : Type'} (R' : A -> Prop) (P : A -> Prop) (Q : A -> Prop), all (fun l : hlist Ctx A => (hand Ctx (@ALL Ctx A R' l) (all (fun x : A => (R' x) -> heq Ctx (P x) (Q x)))) -> heq Ctx (@ALL Ctx A P l) (@ALL Ctx A Q l)).
Axiom thm_ALL_T : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => @ALL Ctx A (fun x : A => htrue Ctx) l).
Axiom thm_MAP_EQ_ALL2 : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => (@ALL2 Ctx A A (fun x : A => fun y : A => heq Ctx (f x) (f y)) l m) -> heq Ctx (@MAP Ctx A B f l) (@MAP Ctx A B f m)))).
Axiom thm_ALL2_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : B -> A -> Prop => all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (@ALL2 Ctx B A P (@MAP Ctx A B f l) l) (@ALL Ctx A (fun a : A => P (f a) a) l)))).
Axiom thm_MAP_EQ_DEGEN : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun f : A -> A => (@ALL Ctx A (fun x : A => heq Ctx (f x) x) l) -> heq Ctx (@MAP Ctx A A f l) l)).
Axiom thm_ALL2_AND_RIGHT : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun l : hlist Ctx A => all (fun m : hlist Ctx B => all (fun P : A -> Prop => all (fun Q : A -> B -> Prop => heq Ctx (@ALL2 Ctx A B (fun x : A => fun y : B => hand Ctx (P x) (Q x y)) l m) (hand Ctx (@ALL Ctx A P l) (@ALL2 Ctx A B Q l m)))))).
Axiom thm_ITLIST_APPEND : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B -> B => all (fun a : B => all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => heq Ctx (@ITLIST Ctx A B f (@APPEND Ctx A l1 l2) a) (@ITLIST Ctx A B f l1 (@ITLIST Ctx A B f l2 a)))))).
Axiom thm_ITLIST_EXTRA : forall (Ctx : HOL_Light_Theory) {A B : Type'} (a : A) (b : B), all (fun f : A -> B -> B => all (fun l : hlist Ctx A => heq Ctx (@ITLIST Ctx A B f (@APPEND Ctx A l (@CONS Ctx A a (@NIL Ctx A))) b) (@ITLIST Ctx A B f l (f a b)))).
Axiom thm_ALL_MP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => all (fun l : hlist Ctx A => (hand Ctx (@ALL Ctx A (fun x : A => (P x) -> Q x) l) (@ALL Ctx A P l)) -> @ALL Ctx A Q l))).
Axiom thm_AND_ALL : forall (Ctx : HOL_Light_Theory) {A : Type'} (P : A -> Prop) (Q : A -> Prop), all (fun l : hlist Ctx A => heq Ctx (hand Ctx (@ALL Ctx A P l) (@ALL Ctx A Q l)) (@ALL Ctx A (fun x : A => hand Ctx (P x) (Q x)) l)).
Axiom thm_EX_IMP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => all (fun l : hlist Ctx A => (hand Ctx (all (fun x : A => (hand Ctx (@MEM Ctx A x l) (P x)) -> Q x)) (@EX Ctx A P l)) -> @EX Ctx A Q l))).
Axiom thm_ALL_MEM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l : hlist Ctx A => heq Ctx (all (fun x : A => (@MEM Ctx A x l) -> P x)) (@ALL Ctx A P l))).
Axiom thm_LENGTH_REPLICATE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun n : num Ctx => all (fun x : A => heq Ctx (@LENGTH Ctx A (@REPLICATE Ctx A n x)) n)).
Axiom thm_MEM_REPLICATE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun n : num Ctx => all (fun x : A => all (fun y : A => heq Ctx (@MEM Ctx A x (@REPLICATE Ctx A n y)) (hand Ctx (heq Ctx x y) (not Ctx (heq Ctx n (NUMERAL Ctx (h0 Ctx)))))))).
Axiom thm_EX_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : B -> Prop => all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (@EX Ctx B P (@MAP Ctx A B f l)) (@EX Ctx A (@o Ctx A B Prop P f) l)))).
Axiom thm_EXISTS_EX : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => all (fun l : hlist Ctx B => heq Ctx (hex Ctx (fun x : A => @EX Ctx B (P x) l)) (@EX Ctx B (fun s : B => hex Ctx (fun x : A => P x s)) l))).
Axiom thm_FORALL_ALL : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => all (fun l : hlist Ctx B => heq Ctx (all (fun x : A => @ALL Ctx B (P x) l)) (@ALL Ctx B (fun s : B => all (fun x : A => P x s)) l))).
Axiom thm_MEM_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => heq Ctx (@MEM Ctx A x (@APPEND Ctx A l1 l2)) (hor Ctx (@MEM Ctx A x l1) (@MEM Ctx A x l2))))).
Axiom thm_MEM_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun y : B => all (fun l : hlist Ctx A => heq Ctx (@MEM Ctx B y (@MAP Ctx A B f l)) (hex Ctx (fun x : A => hand Ctx (@MEM Ctx A x l) (heq Ctx y (f x))))))).
Axiom thm_FILTER_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => heq Ctx (@FILTER Ctx A P (@APPEND Ctx A l1 l2)) (@APPEND Ctx A (@FILTER Ctx A P l1) (@FILTER Ctx A P l2))))).
Axiom thm_FILTER_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : B -> Prop => all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (@FILTER Ctx B P (@MAP Ctx A B f l)) (@MAP Ctx A B f (@FILTER Ctx A (@o Ctx A B Prop P f) l))))).
Axiom thm_MEM_FILTER : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l : hlist Ctx A => all (fun x : A => heq Ctx (@MEM Ctx A x (@FILTER Ctx A P l)) (hand Ctx (P x) (@MEM Ctx A x l))))).
Axiom thm_LENGTH_FILTER : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l : hlist Ctx A => le Ctx (@LENGTH Ctx A (@FILTER Ctx A P l)) (@LENGTH Ctx A l))).
Axiom thm_EX_MEM : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l : hlist Ctx A => heq Ctx (hex Ctx (fun x : A => hand Ctx (P x) (@MEM Ctx A x l))) (@EX Ctx A P l))).
Axiom thm_MAP_FST_ZIP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx B => (heq Ctx (@LENGTH Ctx A l1) (@LENGTH Ctx B l2)) -> heq Ctx (@MAP Ctx (hprod Ctx A B) A (@FST Ctx A B) (@ZIP Ctx A B l1 l2)) l1)).
Axiom thm_MAP_SND_ZIP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx B => (heq Ctx (@LENGTH Ctx A l1) (@LENGTH Ctx B l2)) -> heq Ctx (@MAP Ctx (hprod Ctx A B) B (@SND Ctx A B) (@ZIP Ctx A B l1 l2)) l2)).
Axiom thm_LENGTH_ZIP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx B => (heq Ctx (@LENGTH Ctx A l1) (@LENGTH Ctx B l2)) -> heq Ctx (@LENGTH Ctx (hprod Ctx A B) (@ZIP Ctx A B l1 l2)) (@LENGTH Ctx B l2))).
Axiom thm_MEM_ASSOC : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun l : hlist Ctx (hprod Ctx A B) => all (fun x : A => heq Ctx (@MEM Ctx (hprod Ctx A B) (@hpair Ctx A B x (@ASSOC Ctx A B x l)) l) (@MEM Ctx A x (@MAP Ctx (hprod Ctx A B) A (@FST Ctx A B) l)))).
Axiom thm_ALL_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => heq Ctx (@ALL Ctx A P (@APPEND Ctx A l1 l2)) (hand Ctx (@ALL Ctx A P l1) (@ALL Ctx A P l2))))).
Axiom thm_MEM_EL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun n : num Ctx => (lt Ctx n (@LENGTH Ctx A l)) -> @MEM Ctx A (@EL Ctx A n l) l)).
Axiom thm_MEM_EXISTS_EL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun x : A => heq Ctx (@MEM Ctx A x l) (hex Ctx (fun i : num Ctx => hand Ctx (lt Ctx i (@LENGTH Ctx A l)) (heq Ctx x (@EL Ctx A i l)))))).
Axiom thm_ALL_EL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun l : hlist Ctx A => heq Ctx (all (fun i : num Ctx => (lt Ctx i (@LENGTH Ctx A l)) -> P (@EL Ctx A i l))) (@ALL Ctx A P l))).
Axiom thm_ALL2_MAP2 : forall (Ctx : HOL_Light_Theory) {A B C D : Type'} (P : B -> D -> Prop), all (fun f : A -> B => all (fun g : C -> D => all (fun l : hlist Ctx A => all (fun m : hlist Ctx C => heq Ctx (@ALL2 Ctx B D P (@MAP Ctx A B f l) (@MAP Ctx C D g m)) (@ALL2 Ctx A C (fun x : A => fun y : C => P (f x) (g y)) l m))))).
Axiom thm_AND_ALL2 : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => all (fun Q : A -> B -> Prop => all (fun l : hlist Ctx A => all (fun m : hlist Ctx B => heq Ctx (hand Ctx (@ALL2 Ctx A B P l m) (@ALL2 Ctx A B Q l m)) (@ALL2 Ctx A B (fun x : A => fun y : B => hand Ctx (P x y) (Q x y)) l m))))).
Axiom thm_ALLPAIRS_SYM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => all (fun l : hlist Ctx A => all (fun m : hlist Ctx B => heq Ctx (@ALLPAIRS Ctx A B P l m) (@ALLPAIRS Ctx B A (fun x : B => fun y : A => P y x) m l)))).
Axiom thm_ALLPAIRS_MEM : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun P : A -> B -> Prop => all (fun l : hlist Ctx A => all (fun m : hlist Ctx B => heq Ctx (all (fun x : A => all (fun y : B => (hand Ctx (@MEM Ctx A x l) (@MEM Ctx B y m)) -> P x y))) (@ALLPAIRS Ctx A B P l m)))).
Axiom thm_ALLPAIRS_MAP : forall (Ctx : HOL_Light_Theory) {A B C D : Type'}, all (fun P : B -> D -> Prop => all (fun f : A -> B => all (fun g : C -> D => all (fun l : hlist Ctx A => all (fun m : hlist Ctx C => heq Ctx (@ALLPAIRS Ctx B D P (@MAP Ctx A B f l) (@MAP Ctx C D g m)) (@ALLPAIRS Ctx A C (fun x : A => fun y : C => P (f x) (g y)) l m)))))).
Axiom thm_ALLPAIRS_EQ : forall (Ctx : HOL_Light_Theory) {A B : Type'} (R' : A -> B -> Prop) (R'' : A -> B -> Prop), all (fun l : hlist Ctx A => all (fun m : hlist Ctx B => all (fun P : A -> Prop => all (fun Q : B -> Prop => (hand Ctx (@ALL Ctx A P l) (hand Ctx (@ALL Ctx B Q m) (all (fun p : A => all (fun q : B => (hand Ctx (P p) (Q q)) -> heq Ctx (R' p q) (R'' p q)))))) -> heq Ctx (@ALLPAIRS Ctx A B R' l m) (@ALLPAIRS Ctx A B R'' l m))))).
Axiom thm_ALL2_ALL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> A -> Prop => all (fun l : hlist Ctx A => heq Ctx (@ALL2 Ctx A A P l l) (@ALL Ctx A (fun x : A => P x x) l))).
Axiom thm_APPEND_EQ_NIL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => heq Ctx (heq Ctx (@APPEND Ctx A l m) (@NIL Ctx A)) (hand Ctx (heq Ctx l (@NIL Ctx A)) (heq Ctx m (@NIL Ctx A))))).
Axiom thm_APPEND_LCANCEL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => all (fun l3 : hlist Ctx A => heq Ctx (heq Ctx (@APPEND Ctx A l1 l2) (@APPEND Ctx A l1 l3)) (heq Ctx l2 l3)))).
Axiom thm_APPEND_RCANCEL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => all (fun l3 : hlist Ctx A => heq Ctx (heq Ctx (@APPEND Ctx A l1 l3) (@APPEND Ctx A l2 l3)) (heq Ctx l1 l2)))).
Axiom thm_LENGTH_MAP2 : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : A -> B -> C => all (fun l : hlist Ctx A => all (fun m : hlist Ctx B => (heq Ctx (@LENGTH Ctx A l) (@LENGTH Ctx B m)) -> heq Ctx (@LENGTH Ctx C (@MAP2 Ctx A B C f l m)) (@LENGTH Ctx B m)))).
Axiom thm_EL_MAP2 : forall (Ctx : HOL_Light_Theory) {A B C : Type'}, all (fun f : A -> B -> C => all (fun l : hlist Ctx A => all (fun m : hlist Ctx B => all (fun k : num Ctx => (hand Ctx (lt Ctx k (@LENGTH Ctx A l)) (lt Ctx k (@LENGTH Ctx B m))) -> heq Ctx (@EL Ctx C k (@MAP2 Ctx A B C f l m)) (f (@EL Ctx A k l) (@EL Ctx B k m)))))).
Axiom thm_MAP_EQ_NIL : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (heq Ctx (@MAP Ctx A B f l) (@NIL Ctx B)) (heq Ctx l (@NIL Ctx A)))).
Axiom thm_INJECTIVE_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => heq Ctx (all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => (heq Ctx (@MAP Ctx A B f l) (@MAP Ctx A B f m)) -> heq Ctx l m))) (all (fun x : A => all (fun y : A => (heq Ctx (f x) (f y)) -> heq Ctx x y)))).
Axiom thm_SURJECTIVE_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => heq Ctx (all (fun m : hlist Ctx B => hex Ctx (fun l : hlist Ctx A => heq Ctx (@MAP Ctx A B f l) m))) (all (fun y : B => hex Ctx (fun x : A => heq Ctx (f x) y)))).
Axiom thm_MAP_ID : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (@MAP Ctx A A (fun x : A => x) l) l).
Axiom thm_MAP_I : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@MAP Ctx A A (@I Ctx A)) (@I Ctx (hlist Ctx A)).
Axiom thm_BUTLAST_CLAUSES : forall (Ctx : HOL_Light_Theory) {A : Type'}, hand Ctx (heq Ctx (@BUTLAST Ctx A (@NIL Ctx A)) (@NIL Ctx A)) (hand Ctx (all (fun a : A => heq Ctx (@BUTLAST Ctx A (@CONS Ctx A a (@NIL Ctx A))) (@NIL Ctx A))) (all (fun a : A => all (fun h : A => all (fun t : hlist Ctx A => heq Ctx (@BUTLAST Ctx A (@CONS Ctx A a (@CONS Ctx A h t))) (@CONS Ctx A a (@BUTLAST Ctx A (@CONS Ctx A h t)))))))).
Axiom thm_BUTLAST_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => heq Ctx (@BUTLAST Ctx A (@APPEND Ctx A l m)) (@COND Ctx (hlist Ctx A) (heq Ctx m (@NIL Ctx A)) (@BUTLAST Ctx A l) (@APPEND Ctx A l (@BUTLAST Ctx A m))))).
Axiom thm_APPEND_BUTLAST_LAST : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => (not Ctx (heq Ctx l (@NIL Ctx A))) -> heq Ctx (@APPEND Ctx A (@BUTLAST Ctx A l) (@CONS Ctx A (@LAST Ctx A l) (@NIL Ctx A))) l).
Axiom thm_LAST_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun p : hlist Ctx A => all (fun q : hlist Ctx A => heq Ctx (@LAST Ctx A (@APPEND Ctx A p q)) (@COND Ctx A (heq Ctx q (@NIL Ctx A)) (@LAST Ctx A p) (@LAST Ctx A q)))).
Axiom thm_LENGTH_TL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => (not Ctx (heq Ctx l (@NIL Ctx A))) -> heq Ctx (@LENGTH Ctx A (@TL Ctx A l)) (minus Ctx (@LENGTH Ctx A l) (NUMERAL Ctx (BIT1 Ctx (h0 Ctx))))).
Axiom thm_LAST_REVERSE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => (not Ctx (heq Ctx l (@NIL Ctx A))) -> heq Ctx (@LAST Ctx A (@REVERSE Ctx A l)) (@HD Ctx A l)).
Axiom thm_HD_REVERSE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => (not Ctx (heq Ctx l (@NIL Ctx A))) -> heq Ctx (@HD Ctx A (@REVERSE Ctx A l)) (@LAST Ctx A l)).
Axiom thm_EL_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun k : num Ctx => all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => heq Ctx (@EL Ctx A k (@APPEND Ctx A l m)) (@COND Ctx A (lt Ctx k (@LENGTH Ctx A l)) (@EL Ctx A k l) (@EL Ctx A (minus Ctx k (@LENGTH Ctx A l)) m))))).
Axiom thm_EL_TL : forall (Ctx : HOL_Light_Theory) {A : Type'} (l : hlist Ctx A), all (fun n : num Ctx => heq Ctx (@EL Ctx A n (@TL Ctx A l)) (@EL Ctx A (add Ctx n (NUMERAL Ctx (BIT1 Ctx (h0 Ctx)))) l)).
Axiom thm_EL_CONS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun n : num Ctx => all (fun h : A => all (fun t : hlist Ctx A => heq Ctx (@EL Ctx A n (@CONS Ctx A h t)) (@COND Ctx A (heq Ctx n (NUMERAL Ctx (h0 Ctx))) h (@EL Ctx A (minus Ctx n (NUMERAL Ctx (BIT1 Ctx (h0 Ctx)))) t))))).
Axiom thm_LAST_EL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => (not Ctx (heq Ctx l (@NIL Ctx A))) -> heq Ctx (@LAST Ctx A l) (@EL Ctx A (minus Ctx (@LENGTH Ctx A l) (NUMERAL Ctx (BIT1 Ctx (h0 Ctx)))) l)).
Axiom thm_HD_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => heq Ctx (@HD Ctx A (@APPEND Ctx A l m)) (@COND Ctx A (heq Ctx l (@NIL Ctx A)) (@HD Ctx A m) (@HD Ctx A l)))).
Axiom thm_CONS_HD_TL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => (not Ctx (heq Ctx l (@NIL Ctx A))) -> heq Ctx l (@CONS Ctx A (@HD Ctx A l) (@TL Ctx A l))).
Axiom thm_EL_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun n : num Ctx => all (fun l : hlist Ctx A => (lt Ctx n (@LENGTH Ctx A l)) -> heq Ctx (@EL Ctx B n (@MAP Ctx A B f l)) (f (@EL Ctx A n l))))).
Axiom thm_MAP_REVERSE : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (@REVERSE Ctx B (@MAP Ctx A B f l)) (@MAP Ctx A B f (@REVERSE Ctx A l)))).
Axiom thm_ALL_FILTER : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> Prop => all (fun Q : A -> Prop => all (fun l : hlist Ctx A => heq Ctx (@ALL Ctx A P (@FILTER Ctx A Q l)) (@ALL Ctx A (fun x : A => (Q x) -> P x) l)))).
Axiom thm_APPEND_SING : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun h : A => all (fun t : hlist Ctx A => heq Ctx (@APPEND Ctx A (@CONS Ctx A h (@NIL Ctx A)) t) (@CONS Ctx A h t))).
Axiom thm_MEM_APPEND_DECOMPOSE_LEFT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun l : hlist Ctx A => heq Ctx (@MEM Ctx A x l) (hex Ctx (fun l1 : hlist Ctx A => hex Ctx (fun l2 : hlist Ctx A => hand Ctx (not Ctx (@MEM Ctx A x l1)) (heq Ctx l (@APPEND Ctx A l1 (@CONS Ctx A x l2)))))))).
Axiom thm_MEM_APPEND_DECOMPOSE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun l : hlist Ctx A => heq Ctx (@MEM Ctx A x l) (hex Ctx (fun l1 : hlist Ctx A => hex Ctx (fun l2 : hlist Ctx A => heq Ctx l (@APPEND Ctx A l1 (@CONS Ctx A x l2))))))).
Axiom thm_PAIRWISE_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun R' : A -> A -> Prop => all (fun l : hlist Ctx A => all (fun m : hlist Ctx A => heq Ctx (@PAIRWISE Ctx A R' (@APPEND Ctx A l m)) (hand Ctx (@PAIRWISE Ctx A R' l) (hand Ctx (@PAIRWISE Ctx A R' m) (all (fun x : A => all (fun y : A => (hand Ctx (@MEM Ctx A x l) (@MEM Ctx A y m)) -> R' x y)))))))).
Axiom thm_PAIRWISE_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun R' : B -> B -> Prop => all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (@PAIRWISE Ctx B R' (@MAP Ctx A B f l)) (@PAIRWISE Ctx A (fun x : A => fun y : A => R' (f x) (f y)) l)))).
Axiom thm_PAIRWISE_IMPLIES : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun R' : A -> A -> Prop => all (fun R'' : A -> A -> Prop => all (fun l : hlist Ctx A => (hand Ctx (@PAIRWISE Ctx A R' l) (all (fun x : A => all (fun y : A => (hand Ctx (@MEM Ctx A x l) (hand Ctx (@MEM Ctx A y l) (R' x y))) -> R'' x y)))) -> @PAIRWISE Ctx A R'' l))).
Axiom thm_PAIRWISE_TRANSITIVE : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun R' : A -> A -> Prop => all (fun x : A => all (fun y : A => all (fun l : hlist Ctx A => (all (fun x' : A => all (fun y' : A => all (fun z : A => (hand Ctx (R' x' y') (R' y' z)) -> R' x' z)))) -> heq Ctx (@PAIRWISE Ctx A R' (@CONS Ctx A x (@CONS Ctx A y l))) (hand Ctx (R' x y) (@PAIRWISE Ctx A R' (@CONS Ctx A y l))))))).
Axiom thm_LENGTH_LIST_OF_SEQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : (num Ctx) -> A => all (fun n : num Ctx => heq Ctx (@LENGTH Ctx A (@list_of_seq Ctx A s n)) n)).
Axiom thm_EL_LIST_OF_SEQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : (num Ctx) -> A => all (fun m : num Ctx => all (fun n : num Ctx => (lt Ctx m n) -> heq Ctx (@EL Ctx A m (@list_of_seq Ctx A s n)) (s m)))).
Axiom thm_LIST_OF_SEQ_EQ_NIL : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : (num Ctx) -> A => all (fun n : num Ctx => heq Ctx (heq Ctx (@list_of_seq Ctx A s n) (@NIL Ctx A)) (heq Ctx n (NUMERAL Ctx (h0 Ctx))))).
Axiom thm_LIST_OF_SEQ_EQ_SELF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (@list_of_seq Ctx A (fun i : num Ctx => @EL Ctx A i l) (@LENGTH Ctx A l)) l).
Axiom thm_LENGTH_EQ_LIST_OF_SEQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => all (fun n : num Ctx => heq Ctx (heq Ctx (@LENGTH Ctx A l) n) (heq Ctx l (@list_of_seq Ctx A (fun i : num Ctx => @EL Ctx A i l) n)))).
Axiom thm_MAP_LIST_OF_SEQ : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : (num Ctx) -> A => all (fun g : A -> B => all (fun n : num Ctx => heq Ctx (@MAP Ctx A B g (@list_of_seq Ctx A f n)) (@list_of_seq Ctx B (@o Ctx (num Ctx) A B g f) n)))).
Axiom thm_LIST_OF_SEQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, hand Ctx (all (fun f : (num Ctx) -> A => heq Ctx (@list_of_seq Ctx A f (NUMERAL Ctx (h0 Ctx))) (@NIL Ctx A))) (all (fun f : (num Ctx) -> A => all (fun n : num Ctx => heq Ctx (@list_of_seq Ctx A f (SUC Ctx n)) (@CONS Ctx A (f (NUMERAL Ctx (h0 Ctx))) (@list_of_seq Ctx A (@o Ctx (num Ctx) (num Ctx) A f (SUC Ctx)) n))))).
Axiom thm_MONO_ALL : forall (Ctx : HOL_Light_Theory) {A : Type'} (P : A -> Prop) (Q : A -> Prop) (l : hlist Ctx A), (all (fun x : A => (P x) -> Q x)) -> (@ALL Ctx A P l) -> @ALL Ctx A Q l.
Axiom thm_MONO_ALL2 : forall (Ctx : HOL_Light_Theory) {A B : Type'} (P : A -> B -> Prop) (Q : A -> B -> Prop) (l : hlist Ctx A) (l' : hlist Ctx B), (all (fun x : A => all (fun y : B => (P x y) -> Q x y))) -> (@ALL2 Ctx A B P l l') -> @ALL2 Ctx A B Q l l'.
Axiom thm_char_INDUCT : forall (Ctx : HOL_Light_Theory), all (fun P : (char Ctx) -> Prop => (all (fun a0 : Prop => all (fun a1 : Prop => all (fun a2 : Prop => all (fun a3 : Prop => all (fun a4 : Prop => all (fun a5 : Prop => all (fun a6 : Prop => all (fun a7 : Prop => P (ASCII Ctx a0 a1 a2 a3 a4 a5 a6 a7)))))))))) -> all (fun x : char Ctx => P x)).
Axiom thm_char_RECURSION : forall (Ctx : HOL_Light_Theory) {Z' : Type'}, all (fun f : Prop -> Prop -> Prop -> Prop -> Prop -> Prop -> Prop -> Prop -> Z' => hex Ctx (fun fn : (char Ctx) -> Z' => all (fun a0 : Prop => all (fun a1 : Prop => all (fun a2 : Prop => all (fun a3 : Prop => all (fun a4 : Prop => all (fun a5 : Prop => all (fun a6 : Prop => all (fun a7 : Prop => heq Ctx (fn (ASCII Ctx a0 a1 a2 a3 a4 a5 a6 a7)) (f a0 a1 a2 a3 a4 a5 a6 a7))))))))))).
Axiom thm_DIST_LZERO : forall (Ctx : HOL_Light_Theory), all (fun n : num Ctx => heq Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (NUMERAL Ctx (h0 Ctx)) n)) n).
Axiom thm_DIST_RZERO : forall (Ctx : HOL_Light_Theory), all (fun n : num Ctx => heq Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) n (NUMERAL Ctx (h0 Ctx)))) n).
Axiom thm_DIST_LADD : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun p : num Ctx => all (fun n : num Ctx => heq Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (add Ctx m n) (add Ctx m p))) (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) n p))))).
Axiom thm_DIST_RADD : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun p : num Ctx => all (fun n : num Ctx => heq Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (add Ctx m p) (add Ctx n p))) (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) m n))))).
Axiom thm_DIST_LADD_0 : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun n : num Ctx => heq Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (add Ctx m n) m)) n)).
Axiom thm_DIST_RADD_0 : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun n : num Ctx => heq Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) m (add Ctx m n))) n)).
Axiom thm_DIST_LMUL : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun n : num Ctx => all (fun p : num Ctx => heq Ctx (mul Ctx m (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) n p))) (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (mul Ctx m n) (mul Ctx m p)))))).
Axiom thm_DIST_RMUL : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun n : num Ctx => all (fun p : num Ctx => heq Ctx (mul Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) m n)) p) (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (mul Ctx m p) (mul Ctx n p)))))).
Axiom thm_DIST_ELIM_THM : forall (Ctx : HOL_Light_Theory) (y : num Ctx) (x : num Ctx) (P : (num Ctx) -> Prop), heq Ctx (P (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) x y))) (all (fun d : num Ctx => hand Ctx ((heq Ctx x (add Ctx y d)) -> P d) ((heq Ctx y (add Ctx x d)) -> P d))).
Axiom thm_DIST_TRIANGLES_LE : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun n : num Ctx => all (fun p : num Ctx => all (fun q : num Ctx => all (fun r : num Ctx => all (fun s : num Ctx => (hand Ctx (le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) m n)) r) (le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) p q)) s)) -> le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) m p)) (add Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) n q)) (add Ctx r s)))))))).
Axiom thm_BOUNDS_LINEAR : forall (Ctx : HOL_Light_Theory), all (fun A : num Ctx => all (fun B : num Ctx => all (fun C : num Ctx => heq Ctx (all (fun n : num Ctx => le Ctx (mul Ctx A n) (add Ctx (mul Ctx B n) C))) (le Ctx A B)))).
Axiom thm_BOUNDS_LINEAR_0 : forall (Ctx : HOL_Light_Theory), all (fun A : num Ctx => all (fun B : num Ctx => heq Ctx (all (fun n : num Ctx => le Ctx (mul Ctx A n) B)) (heq Ctx A (NUMERAL Ctx (h0 Ctx))))).
Axiom thm_BOUNDS_DIVIDED : forall (Ctx : HOL_Light_Theory), all (fun P : (num Ctx) -> num Ctx => heq Ctx (hex Ctx (fun B : num Ctx => all (fun n : num Ctx => le Ctx (P n) B))) (hex Ctx (fun A : num Ctx => hex Ctx (fun B : num Ctx => all (fun n : num Ctx => le Ctx (mul Ctx n (P n)) (add Ctx (mul Ctx A n) B)))))).
Axiom thm_BOUNDS_NOTZERO : forall (Ctx : HOL_Light_Theory), all (fun P : (num Ctx) -> (num Ctx) -> num Ctx => all (fun A : num Ctx => all (fun B : num Ctx => (hand Ctx (heq Ctx (P (NUMERAL Ctx (h0 Ctx)) (NUMERAL Ctx (h0 Ctx))) (NUMERAL Ctx (h0 Ctx))) (all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (P m n) (add Ctx (mul Ctx A (add Ctx m n)) B))))) -> hex Ctx (fun B' : num Ctx => all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (P m n) (mul Ctx B' (add Ctx m n)))))))).
Axiom thm_BOUNDS_IGNORE : forall (Ctx : HOL_Light_Theory), all (fun P : (num Ctx) -> num Ctx => all (fun Q : (num Ctx) -> num Ctx => heq Ctx (hex Ctx (fun B : num Ctx => all (fun i : num Ctx => le Ctx (P i) (add Ctx (Q i) B)))) (hex Ctx (fun B : num Ctx => hex Ctx (fun N' : num Ctx => all (fun i : num Ctx => (le Ctx N' i) -> le Ctx (P i) (add Ctx (Q i) B))))))).
Axiom thm_is_nadd : forall (Ctx : HOL_Light_Theory), all (fun x : (num Ctx) -> num Ctx => heq Ctx (is_nadd Ctx x) (hex Ctx (fun B : num Ctx => all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (mul Ctx m (x n)) (mul Ctx n (x m)))) (mul Ctx B (add Ctx m n))))))).
Axiom thm_is_nadd_0 : forall (Ctx : HOL_Light_Theory), is_nadd Ctx (fun n : num Ctx => NUMERAL Ctx (h0 Ctx)).
Axiom thm_NADD_CAUCHY : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => hex Ctx (fun B : num Ctx => all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (mul Ctx m (dest_nadd Ctx x n)) (mul Ctx n (dest_nadd Ctx x m)))) (mul Ctx B (add Ctx m n)))))).
Axiom thm_NADD_BOUND : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => hex Ctx (fun A : num Ctx => hex Ctx (fun B : num Ctx => all (fun n : num Ctx => le Ctx (dest_nadd Ctx x n) (add Ctx (mul Ctx A n) B))))).
Axiom thm_NADD_MULTIPLICATIVE : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => hex Ctx (fun B : num Ctx => all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (dest_nadd Ctx x (mul Ctx m n)) (mul Ctx m (dest_nadd Ctx x n)))) (add Ctx (mul Ctx B m) B))))).
Axiom thm_NADD_ADDITIVE : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => hex Ctx (fun B : num Ctx => all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (dest_nadd Ctx x (add Ctx m n)) (add Ctx (dest_nadd Ctx x m) (dest_nadd Ctx x n)))) B)))).
Axiom thm_NADD_SUC : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => hex Ctx (fun B : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (dest_nadd Ctx x (SUC Ctx n)) (dest_nadd Ctx x n))) B))).
Axiom thm_NADD_DIST_LEMMA : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => hex Ctx (fun B : num Ctx => all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (dest_nadd Ctx x (add Ctx m n)) (dest_nadd Ctx x m))) (mul Ctx B n))))).
Axiom thm_NADD_DIST : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => hex Ctx (fun B : num Ctx => all (fun m : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (dest_nadd Ctx x m) (dest_nadd Ctx x n))) (mul Ctx B (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) m n))))))).
Axiom thm_NADD_ALTMUL : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => all (fun y : nadd Ctx => hex Ctx (fun A : num Ctx => hex Ctx (fun B : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (mul Ctx n (dest_nadd Ctx x (dest_nadd Ctx y n))) (mul Ctx (dest_nadd Ctx x n) (dest_nadd Ctx y n)))) (add Ctx (mul Ctx A n) B)))))).
Axiom thm_nadd_eq : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => all (fun y : nadd Ctx => heq Ctx (nadd_eq Ctx x y) (hex Ctx (fun B : num Ctx => all (fun n : num Ctx => le Ctx (dist Ctx (@hpair Ctx (num Ctx) (num Ctx) (dest_nadd Ctx x n) (dest_nadd Ctx y n))) B))))).
Axiom thm_NADD_EQ_REFL : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => nadd_eq Ctx x x).
Axiom thm_NADD_EQ_SYM : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => all (fun y : nadd Ctx => heq Ctx (nadd_eq Ctx x y) (nadd_eq Ctx y x))).
Axiom thm_NADD_EQ_TRANS : forall (Ctx : HOL_Light_Theory), all (fun x : nadd Ctx => all (fun y : nadd Ctx => all (fun z : nadd Ctx => (hand Ctx (nadd_eq Ctx x y) (nadd_eq Ctx y z)) -> nadd_eq Ctx x z))).
Axiom thm_nadd_of_num : forall (Ctx : HOL_Light_Theory), all (fun k : num Ctx => heq Ctx (nadd_of_num Ctx k) (mk_nadd Ctx (fun n : num Ctx => mul Ctx k n))).
Axiom thm_NADD_OF_NUM : forall (Ctx : HOL_Light_Theory), all (fun k : num Ctx => heq Ctx (dest_nadd Ctx (nadd_of_num Ctx k)) (fun n : num Ctx => mul Ctx k n)).
Axiom thm_NADD_OF_NUM_WELLDEF : forall (Ctx : HOL_Light_Theory), all (fun m : num Ctx => all (fun n : num Ctx => (heq Ctx m n) -> nadd_eq Ctx (nadd_of_num Ctx m) (nadd_of_num Ctx n))).
