Axiom thm_DIFF_DIFF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : A -> Prop => all (fun t : A -> Prop => heq Ctx (@DIFF Ctx A (@DIFF Ctx A s t) t) (@DIFF Ctx A s t))).
