Axiom thm_INSERT_UNION_EQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun s : A -> Prop => all (fun t : A -> Prop => heq Ctx (@UNION Ctx A (@INSERT Ctx A x s) t) (@INSERT Ctx A x (@UNION Ctx A s t))))).
