Axiom thm_DISJOINT_INSERT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun s : A -> Prop => all (fun t : A -> Prop => heq Ctx (@DISJOINT Ctx A (@INSERT Ctx A x s) t) (hand Ctx (@DISJOINT Ctx A s t) (not Ctx (@IN Ctx A x t)))))).
