Axiom thm_SUBSET_INSERT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun s : A -> Prop => (not Ctx (@IN Ctx A x s)) -> all (fun t : A -> Prop => heq Ctx (@SUBSET Ctx A s (@INSERT Ctx A x t)) (@SUBSET Ctx A s t)))).
Axiom thm_INSERT_DIFF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : A -> Prop => all (fun t : A -> Prop => all (fun x : A => heq Ctx (@DIFF Ctx A (@INSERT Ctx A x s) t) (@COND Ctx (A -> Prop) (@IN Ctx A x t) (@DIFF Ctx A s t) (@INSERT Ctx A x (@DIFF Ctx A s t)))))).
Axiom thm_INSERT_AC : forall (Ctx : HOL_Light_Theory) {A : Type'} (y : A) (x : A) (s : A -> Prop), hand Ctx (heq Ctx (@INSERT Ctx A x (@INSERT Ctx A y s)) (@INSERT Ctx A y (@INSERT Ctx A x s))) (heq Ctx (@INSERT Ctx A x (@INSERT Ctx A x s)) (@INSERT Ctx A x s)).
Axiom thm_INTER_ACI : forall (Ctx : HOL_Light_Theory) {A : Type'} (r : A -> Prop) (p : A -> Prop) (q : A -> Prop), hand Ctx (heq Ctx (@INTER Ctx A p q) (@INTER Ctx A q p)) (hand Ctx (heq Ctx (@INTER Ctx A (@INTER Ctx A p q) r) (@INTER Ctx A p (@INTER Ctx A q r))) (hand Ctx (heq Ctx (@INTER Ctx A p (@INTER Ctx A q r)) (@INTER Ctx A q (@INTER Ctx A p r))) (hand Ctx (heq Ctx (@INTER Ctx A p p) p) (heq Ctx (@INTER Ctx A p (@INTER Ctx A p q)) (@INTER Ctx A p q))))).
