Axiom thm_FINITE_SET_OF_LIST : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => @FINITE Ctx A (@set_of_list Ctx A l)).
Axiom thm_IN_SET_OF_LIST : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun x : A => all (fun l : hlist Ctx A => heq Ctx (@IN Ctx A x (@set_of_list Ctx A l)) (@MEM Ctx A x l))).
Axiom thm_SET_OF_LIST_APPEND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l1 : hlist Ctx A => all (fun l2 : hlist Ctx A => heq Ctx (@set_of_list Ctx A (@APPEND Ctx A l1 l2)) (@UNION Ctx A (@set_of_list Ctx A l1) (@set_of_list Ctx A l2)))).
Axiom thm_SET_OF_LIST_MAP : forall (Ctx : HOL_Light_Theory) {A B : Type'}, all (fun f : A -> B => all (fun l : hlist Ctx A => heq Ctx (@set_of_list Ctx B (@MAP Ctx A B f l)) (@IMAGE Ctx A B f (@set_of_list Ctx A l)))).
Axiom thm_SET_OF_LIST_EQ_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun l : hlist Ctx A => heq Ctx (heq Ctx (@set_of_list Ctx A l) (@EMPTY Ctx A)) (heq Ctx l (@NIL Ctx A))).
Axiom thm_LIST_OF_SET_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, heq Ctx (@list_of_set Ctx A (@EMPTY Ctx A)) (@NIL Ctx A).
Axiom thm_LIST_OF_SET_SING : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun a : A => heq Ctx (@list_of_set Ctx A (@INSERT Ctx A a (@EMPTY Ctx A))) (@CONS Ctx A a (@NIL Ctx A))).
Axiom thm_pairwise : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : A -> Prop => all (fun r : A -> A -> Prop => heq Ctx (@pairwise Ctx A r s) (all (fun x : A => all (fun y : A => (hand Ctx (@IN Ctx A x s) (hand Ctx (@IN Ctx A y s) (not Ctx (heq Ctx x y)))) -> r x y))))).
Axiom thm_PAIRWISE_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun r : A -> A -> Prop => heq Ctx (@pairwise Ctx A r (@EMPTY Ctx A)) (htrue Ctx)).
Axiom thm_PAIRWISE_SING : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun r : A -> A -> Prop => all (fun x : A => heq Ctx (@pairwise Ctx A r (@INSERT Ctx A x (@EMPTY Ctx A))) (htrue Ctx))).
Axiom thm_PAIRWISE_IMP : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : A -> A -> Prop => all (fun Q : A -> A -> Prop => all (fun s : A -> Prop => (hand Ctx (@pairwise Ctx A P s) (all (fun x : A => all (fun y : A => (hand Ctx (@IN Ctx A x s) (hand Ctx (@IN Ctx A y s) (hand Ctx (P x y) (not Ctx (heq Ctx x y))))) -> Q x y)))) -> @pairwise Ctx A Q s))).
Axiom thm_PAIRWISE_MONO : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun r : A -> A -> Prop => all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@pairwise Ctx A r s) (@SUBSET Ctx A t s)) -> @pairwise Ctx A r t))).
Axiom thm_PAIRWISE_AND : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun R' : A -> A -> Prop => all (fun R'' : A -> A -> Prop => all (fun s : A -> Prop => heq Ctx (hand Ctx (@pairwise Ctx A R' s) (@pairwise Ctx A R'' s)) (@pairwise Ctx A (fun x : A => fun y : A => hand Ctx (R' x y) (R'' x y)) s)))).
Axiom thm_PAIRWISE_INSERT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun r : A -> A -> Prop => all (fun x : A => all (fun s : A -> Prop => heq Ctx (@pairwise Ctx A r (@INSERT Ctx A x s)) (hand Ctx (all (fun y : A => (hand Ctx (@IN Ctx A y s) (not Ctx (heq Ctx y x))) -> hand Ctx (r x y) (r y x))) (@pairwise Ctx A r s))))).
Axiom thm_PAIRWISE_INSERT_SYMMETRIC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun r : A -> A -> Prop => all (fun x : A => all (fun s : A -> Prop => (all (fun y : A => (@IN Ctx A y s) -> heq Ctx (r x y) (r y x))) -> heq Ctx (@pairwise Ctx A r (@INSERT Ctx A x s)) (hand Ctx (all (fun y : A => (hand Ctx (@IN Ctx A y s) (not Ctx (heq Ctx y x))) -> r x y)) (@pairwise Ctx A r s))))).
Axiom thm_PAIRWISE_IMAGE : forall (Ctx : HOL_Light_Theory) {A B : Type'} (s : A -> Prop), all (fun r : B -> B -> Prop => all (fun f : A -> B => heq Ctx (@pairwise Ctx B r (@IMAGE Ctx A B f s)) (@pairwise Ctx A (fun x : A => fun y : A => (not Ctx (heq Ctx (f x) (f y))) -> r (f x) (f y)) s))).
Axiom thm_PAIRWISE_UNION : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun R' : A -> A -> Prop => all (fun s : A -> Prop => all (fun t : A -> Prop => heq Ctx (@pairwise Ctx A R' (@UNION Ctx A s t)) (hand Ctx (@pairwise Ctx A R' s) (hand Ctx (@pairwise Ctx A R' t) (all (fun x : A => all (fun y : A => (hand Ctx (@IN Ctx A x (@DIFF Ctx A s t)) (@IN Ctx A y (@DIFF Ctx A t s))) -> hand Ctx (R' x y) (R' y x))))))))).
Axiom thm_PAIRWISE_CHAIN_UNIONS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun R' : A -> A -> Prop => all (fun c : (A -> Prop) -> Prop => (hand Ctx (all (fun s : A -> Prop => (@IN Ctx (A -> Prop) s c) -> @pairwise Ctx A R' s)) (all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@IN Ctx (A -> Prop) s c) (@IN Ctx (A -> Prop) t c)) -> hor Ctx (@SUBSET Ctx A s t) (@SUBSET Ctx A t s))))) -> @pairwise Ctx A R' (@UNIONS Ctx A c))).
Axiom thm_DIFF_UNIONS_PAIRWISE_DISJOINT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : (A -> Prop) -> Prop => all (fun t : (A -> Prop) -> Prop => (hand Ctx (@pairwise Ctx (A -> Prop) (@DISJOINT Ctx A) s) (@SUBSET Ctx (A -> Prop) t s)) -> heq Ctx (@DIFF Ctx A (@UNIONS Ctx A s) (@UNIONS Ctx A t)) (@UNIONS Ctx A (@DIFF Ctx (A -> Prop) s t)))).
Axiom thm_INTER_UNIONS_PAIRWISE_DISJOINT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : (A -> Prop) -> Prop => all (fun t : (A -> Prop) -> Prop => (@pairwise Ctx (A -> Prop) (@DISJOINT Ctx A) (@UNION Ctx (A -> Prop) s t)) -> heq Ctx (@INTER Ctx A (@UNIONS Ctx A s) (@UNIONS Ctx A t)) (@UNIONS Ctx A (@INTER Ctx (A -> Prop) s t)))).
Axiom thm_PSUBSET_UNIONS_PAIRWISE_DISJOINT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun u : (A -> Prop) -> Prop => all (fun v : (A -> Prop) -> Prop => (hand Ctx (@pairwise Ctx (A -> Prop) (@DISJOINT Ctx A) v) (@PSUBSET Ctx (A -> Prop) u (@DELETE Ctx (A -> Prop) v (@EMPTY Ctx A)))) -> @PSUBSET Ctx A (@UNIONS Ctx A u) (@UNIONS Ctx A v))).
Axiom thm_UNION_OF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => heq Ctx (@UNION_OF Ctx A P Q) (fun s : A -> Prop => hex Ctx (fun u : (A -> Prop) -> Prop => hand Ctx (P u) (hand Ctx (all (fun c : A -> Prop => (@IN Ctx (A -> Prop) c u) -> Q c)) (heq Ctx (@UNIONS Ctx A u) s)))))).
Axiom thm_INTERSECTION_OF : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => heq Ctx (@INTERSECTION_OF Ctx A P Q) (fun s : A -> Prop => hex Ctx (fun u : (A -> Prop) -> Prop => hand Ctx (P u) (hand Ctx (all (fun c : A -> Prop => (@IN Ctx (A -> Prop) c u) -> Q c)) (heq Ctx (@INTERS Ctx A u) s)))))).
Axiom thm_UNION_OF_INC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => all (fun s : A -> Prop => (hand Ctx (P (@INSERT Ctx (A -> Prop) s (@EMPTY Ctx (A -> Prop)))) (Q s)) -> @UNION_OF Ctx A P Q s))).
Axiom thm_INTERSECTION_OF_INC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => all (fun s : A -> Prop => (hand Ctx (P (@INSERT Ctx (A -> Prop) s (@EMPTY Ctx (A -> Prop)))) (Q s)) -> @INTERSECTION_OF Ctx A P Q s))).
Axiom thm_UNION_OF_MONO : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => all (fun Q' : (A -> Prop) -> Prop => all (fun s : A -> Prop => (hand Ctx (@UNION_OF Ctx A P Q s) (all (fun x : A -> Prop => (Q x) -> Q' x))) -> @UNION_OF Ctx A P Q' s)))).
Axiom thm_INTERSECTION_OF_MONO : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => all (fun Q' : (A -> Prop) -> Prop => all (fun s : A -> Prop => (hand Ctx (@INTERSECTION_OF Ctx A P Q s) (all (fun x : A -> Prop => (Q x) -> Q' x))) -> @INTERSECTION_OF Ctx A P Q' s)))).
Axiom thm_FORALL_UNION_OF : forall (Ctx : HOL_Light_Theory) {A : Type'} (P : ((A -> Prop) -> Prop) -> Prop) (Q : (A -> Prop) -> Prop) (R' : (A -> Prop) -> Prop), heq Ctx (all (fun s : A -> Prop => (@UNION_OF Ctx A P Q s) -> R' s)) (all (fun t : (A -> Prop) -> Prop => (hand Ctx (P t) (all (fun c : A -> Prop => (@IN Ctx (A -> Prop) c t) -> Q c))) -> R' (@UNIONS Ctx A t))).
Axiom thm_FORALL_INTERSECTION_OF : forall (Ctx : HOL_Light_Theory) {A : Type'} (P : ((A -> Prop) -> Prop) -> Prop) (Q : (A -> Prop) -> Prop) (R' : (A -> Prop) -> Prop), heq Ctx (all (fun s : A -> Prop => (@INTERSECTION_OF Ctx A P Q s) -> R' s)) (all (fun t : (A -> Prop) -> Prop => (hand Ctx (P t) (all (fun c : A -> Prop => (@IN Ctx (A -> Prop) c t) -> Q c))) -> R' (@INTERS Ctx A t))).
Axiom thm_UNION_OF_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => (P (@EMPTY Ctx (A -> Prop))) -> @UNION_OF Ctx A P Q (@EMPTY Ctx A))).
Axiom thm_INTERSECTION_OF_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : ((A -> Prop) -> Prop) -> Prop => all (fun Q : (A -> Prop) -> Prop => (P (@EMPTY Ctx (A -> Prop))) -> @INTERSECTION_OF Ctx A P Q (@UNIV Ctx A))).
Axiom thm_ARBITRARY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun s : (A -> Prop) -> Prop => heq Ctx (@ARBITRARY Ctx A s) (htrue Ctx)).
Axiom thm_ARBITRARY_UNION_OF_ALT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun B : (A -> Prop) -> Prop => all (fun s : A -> Prop => heq Ctx (@UNION_OF Ctx A (@ARBITRARY Ctx A) B s) (all (fun x : A => (@IN Ctx A x s) -> hex Ctx (fun u : A -> Prop => hand Ctx (@IN Ctx (A -> Prop) u B) (hand Ctx (@IN Ctx A x u) (@SUBSET Ctx A u s))))))).
Axiom thm_ARBITRARY_UNION_OF_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => @UNION_OF Ctx A (@ARBITRARY Ctx A) P (@EMPTY Ctx A)).
Axiom thm_ARBITRARY_INTERSECTION_OF_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P (@UNIV Ctx A)).
Axiom thm_ARBITRARY_UNION_OF_INC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => (P s) -> @UNION_OF Ctx A (@ARBITRARY Ctx A) P s)).
Axiom thm_ARBITRARY_INTERSECTION_OF_INC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => (P s) -> @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P s)).
Axiom thm_ARBITRARY_UNION_OF_COMPLEMENT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => heq Ctx (@UNION_OF Ctx A (@ARBITRARY Ctx A) P s) (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) (fun s' : A -> Prop => P (@DIFF Ctx A (@UNIV Ctx A) s')) (@DIFF Ctx A (@UNIV Ctx A) s)))).
Axiom thm_ARBITRARY_INTERSECTION_OF_COMPLEMENT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => heq Ctx (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P s) (@UNION_OF Ctx A (@ARBITRARY Ctx A) (fun s' : A -> Prop => P (@DIFF Ctx A (@UNIV Ctx A) s')) (@DIFF Ctx A (@UNIV Ctx A) s)))).
Axiom thm_ARBITRARY_UNION_OF_IDEMPOT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => heq Ctx (@UNION_OF Ctx A (@ARBITRARY Ctx A) (@UNION_OF Ctx A (@ARBITRARY Ctx A) P)) (@UNION_OF Ctx A (@ARBITRARY Ctx A) P)).
Axiom thm_ARBITRARY_INTERSECTION_OF_IDEMPOT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => heq Ctx (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P)) (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P)).
Axiom thm_ARBITRARY_UNION_OF_UNIONS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun u : (A -> Prop) -> Prop => (all (fun s : A -> Prop => (@IN Ctx (A -> Prop) s u) -> @UNION_OF Ctx A (@ARBITRARY Ctx A) P s)) -> @UNION_OF Ctx A (@ARBITRARY Ctx A) P (@UNIONS Ctx A u))).
Axiom thm_ARBITRARY_UNION_OF_UNION : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@UNION_OF Ctx A (@ARBITRARY Ctx A) P s) (@UNION_OF Ctx A (@ARBITRARY Ctx A) P t)) -> @UNION_OF Ctx A (@ARBITRARY Ctx A) P (@UNION Ctx A s t)))).
Axiom thm_ARBITRARY_INTERSECTION_OF_INTERS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun u : (A -> Prop) -> Prop => (all (fun s : A -> Prop => (@IN Ctx (A -> Prop) s u) -> @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P s)) -> @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P (@INTERS Ctx A u))).
Axiom thm_ARBITRARY_INTERSECTION_OF_INTER : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P s) (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P t)) -> @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P (@INTER Ctx A s t)))).
Axiom thm_ARBITRARY_UNION_OF_INTER_EQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => heq Ctx (all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@UNION_OF Ctx A (@ARBITRARY Ctx A) P s) (@UNION_OF Ctx A (@ARBITRARY Ctx A) P t)) -> @UNION_OF Ctx A (@ARBITRARY Ctx A) P (@INTER Ctx A s t)))) (all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (P s) (P t)) -> @UNION_OF Ctx A (@ARBITRARY Ctx A) P (@INTER Ctx A s t))))).
Axiom thm_ARBITRARY_UNION_OF_INTER : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => (all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (P s) (P t)) -> P (@INTER Ctx A s t)))) -> all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@UNION_OF Ctx A (@ARBITRARY Ctx A) P s) (@UNION_OF Ctx A (@ARBITRARY Ctx A) P t)) -> @UNION_OF Ctx A (@ARBITRARY Ctx A) P (@INTER Ctx A s t)))).
Axiom thm_ARBITRARY_INTERSECTION_OF_UNION_EQ : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => heq Ctx (all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P s) (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P t)) -> @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P (@UNION Ctx A s t)))) (all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (P s) (P t)) -> @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P (@UNION Ctx A s t))))).
Axiom thm_ARBITRARY_INTERSECTION_OF_UNION : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => (all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (P s) (P t)) -> P (@UNION Ctx A s t)))) -> all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P s) (@INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P t)) -> @INTERSECTION_OF Ctx A (@ARBITRARY Ctx A) P (@UNION Ctx A s t)))).
Axiom thm_FINITE_UNION_OF_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => @UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P (@EMPTY Ctx A)).
Axiom thm_FINITE_INTERSECTION_OF_EMPTY : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => @INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P (@UNIV Ctx A)).
Axiom thm_FINITE_UNION_OF_INC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => (P s) -> @UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s)).
Axiom thm_FINITE_INTERSECTION_OF_INC : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => (P s) -> @INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s)).
Axiom thm_FINITE_UNION_OF_COMPLEMENT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => heq Ctx (@UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s) (@INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) (fun s' : A -> Prop => P (@DIFF Ctx A (@UNIV Ctx A) s')) (@DIFF Ctx A (@UNIV Ctx A) s)))).
Axiom thm_FINITE_INTERSECTION_OF_COMPLEMENT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => heq Ctx (@INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s) (@UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) (fun s' : A -> Prop => P (@DIFF Ctx A (@UNIV Ctx A) s')) (@DIFF Ctx A (@UNIV Ctx A) s)))).
Axiom thm_FINITE_UNION_OF_IDEMPOT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => heq Ctx (@UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) (@UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P)) (@UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P)).
Axiom thm_FINITE_INTERSECTION_OF_IDEMPOT : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => heq Ctx (@INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) (@INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P)) (@INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P)).
Axiom thm_FINITE_UNION_OF_UNIONS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun u : (A -> Prop) -> Prop => (hand Ctx (@FINITE Ctx (A -> Prop) u) (all (fun s : A -> Prop => (@IN Ctx (A -> Prop) s u) -> @UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s))) -> @UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P (@UNIONS Ctx A u))).
Axiom thm_FINITE_UNION_OF_UNION : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s) (@UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P t)) -> @UNION_OF Ctx A (@FINITE Ctx (A -> Prop)) P (@UNION Ctx A s t)))).
Axiom thm_FINITE_INTERSECTION_OF_INTERS : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun u : (A -> Prop) -> Prop => (hand Ctx (@FINITE Ctx (A -> Prop) u) (all (fun s : A -> Prop => (@IN Ctx (A -> Prop) s u) -> @INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s))) -> @INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P (@INTERS Ctx A u))).
Axiom thm_FINITE_INTERSECTION_OF_INTER : forall (Ctx : HOL_Light_Theory) {A : Type'}, all (fun P : (A -> Prop) -> Prop => all (fun s : A -> Prop => all (fun t : A -> Prop => (hand Ctx (@INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P s) (@INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P t)) -> @INTERSECTION_OF Ctx A (@FINITE Ctx (A -> Prop)) P (@INTER Ctx A s t)))).
